@dataclass
class AudioFeatures:
    """Comprehensive audio feature representation"""
    # Basic temporal features
    duration: float
    sample_rate: int
    
    # Rhythm and tempo
    tempo: float
    beat_confidence: float
    time_signature: TimeSignature
    rhythm_regularity: float
    
    # Spectral features
    spectral_centroid: np.ndarray
    spectral_rolloff: np.ndarray
    spectral_bandwidth: np.ndarray
    spectral_contrast: np.ndarray
    spectral_flatness: np.ndarray
    
    # Energy features
    rms_energy: np.ndarray
    zero_crossing_rate: np.ndarray
    harmonic_energy: float
    percussive_energy: float
    
    # Harmonic features
    chroma: np.ndarray
    tonnetz: np.ndarray
    key: MusicalKey
    key_confidence: float
    
    # Timbral features
    mfccs: np.ndarray
    mel_spectrogram: np.ndarray
    
    # High-level descriptors
    valence: float  # 0-1 (negative to positive)
    arousal: float  # 0-1 (calm to energetic)
    danceability: float
    energy: float
    acousticness: float
    instrumentalness: float
    liveness: float
    speechiness: float
    loudness: float
    
    # Onset and segmentation
    onsets: np.ndarray
    segments: List[Tuple[float, float]]
    
    def to_dict(self) -> Dict[str, Any]:
        """Convert to dictionary for serialization"""
        return {
            'duration': self.duration,
            'sample_rate': self.sample_rate,
            'tempo': self.tempo,
            'beat_confidence': self.beat_confidence,
            'time_signature': self.time_signature.value,
            'rhythm_regularity': self.rhythm_regularity,
            'spectral_centroid_mean': float(np.mean(self.spectral_centroid)),
            'spectral_centroid_std': float(np.std(self.spectral_centroid)),
            'spectral_rolloff_mean': float(np.mean(self.spectral_rolloff)),
            'spectral_bandwidth_mean': float(np.mean(self.spectral_bandwidth)),
            'spectral_contrast_mean': float(np.mean(self.spectral_contrast)),
            'rms_energy_mean': float(np.mean(self.rms_energy)),
            'rms_energy_std': float(np.std(self.rms_energy)),
            'zcr_mean': float(np.mean(self.zero_crossing_rate)),
            'harmonic_energy': self.harmonic_energy,
            'percussive_energy': self.percussive_energy,
            'chroma_mean': self.chroma.mean(axis=1).tolist(),
            'tonnetz_mean': self.tonnetz.mean(axis=1).tolist(),
            'key': self.key.value,
            'key_confidence': self.key_confidence,
            'mfccs_mean': self.mfccs.mean(axis=1).tolist(),
            'valence': self.valence,
            'arousal': self.arousal,
            'danceability': self.danceability,
            'energy': self.energy,
            'acousticness': self.acousticness,
            'instrumentalness': self.instrumentalness,
            'liveness': self.liveness,
            'speechiness': self.speechiness,
            'loudness': self.loudness,
            'onset_count': len(self.onsets),
            'segment_count': len(self.segments)
        }


