"""
🎵 Spotify AI Agent - Audio Neural Networks Module
================================================

This module contains specialized neural network architectures optimized
for audio processing, music analysis, and audio feature extraction.
It provides state-of-the-art deep learning models for various audio tasks
including audio classification, music generation, and audio enhancement.

Audio Network Components:
- Audio preprocessing and feature extraction
- Spectral neural networks for frequency analysis
- Temporal neural networks for sequence modeling
- Hybrid audio-visual networks
- Music generation and synthesis networks
- Audio enhancement and denoising networks
"""

import numpy as np
import librosa
import soundfile as sf
from typing import Dict, List, Tuple, Optional, Union, Any
import tensorflow as tf
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import Dataset
import torchaudio
import torchaudio.transforms as T

from .core_networks import BaseNeuralNetwork, NetworkConfig, TrainingMetrics
import logging

logger = logging.getLogger(__name__)


class AudioConfig(NetworkConfig):
    """Extended configuration for audio neural networks."""
    
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        
        # Audio-specific parameters
        self.sample_rate: int = kwargs.get('sample_rate', 22050)
        self.n_fft: int = kwargs.get('n_fft', 2048)
        self.hop_length: int = kwargs.get('hop_length', 512)
        self.n_mels: int = kwargs.get('n_mels', 128)
        self.n_mfcc: int = kwargs.get('n_mfcc', 13)
        
        # Spectrogram parameters
        self.window_size: int = kwargs.get('window_size', 1024)
        self.overlap: float = kwargs.get('overlap', 0.5)
        self.mel_scale: bool = kwargs.get('mel_scale', True)
        
        # Audio preprocessing
        self.normalize_audio: bool = kwargs.get('normalize_audio', True)
        self.apply_windowing: bool = kwargs.get('apply_windowing', True)
        self.pre_emphasis: float = kwargs.get('pre_emphasis', 0.97)
        
        # Advanced audio features
        self.use_chromagram: bool = kwargs.get('use_chromagram', False)
        self.use_spectral_centroid: bool = kwargs.get('use_spectral_centroid', False)
        self.use_zero_crossing_rate: bool = kwargs.get('use_zero_crossing_rate', False)
        self.use_tempo: bool = kwargs.get('use_tempo', False)
        
        # Audio augmentation
        self.time_stretch: bool = kwargs.get('time_stretch', False)
        self.pitch_shift: bool = kwargs.get('pitch_shift', False)
        self.add_noise: bool = kwargs.get('add_noise', False)
        self.dynamic_range_compression: bool = kwargs.get('dynamic_range_compression', False)


class AudioPreprocessor:
    """
    Advanced audio preprocessing pipeline for neural networks.
    
    Provides comprehensive audio feature extraction, normalization,
    and augmentation capabilities for training and inference.
    """
    
    def __init__(self, config: AudioConfig):
        self.config = config
        self.feature_extractors = self._initialize_extractors()
        
    def _initialize_extractors(self) -> Dict[str, Any]:
        """Initialize audio feature extractors."""
        extractors = {}
        
        # Mel-scale spectrogram
        if self.config.mel_scale:
            extractors['mel_spectrogram'] = {
                'n_fft': self.config.n_fft,
                'hop_length': self.config.hop_length,
                'n_mels': self.config.n_mels,
                'sr': self.config.sample_rate
            }
        
        # MFCC features
        extractors['mfcc'] = {
            'n_mfcc': self.config.n_mfcc,
            'n_fft': self.config.n_fft,
            'hop_length': self.config.hop_length
        }
        
        # Chromagram features
        if self.config.use_chromagram:
            extractors['chromagram'] = {
                'hop_length': self.config.hop_length,
                'sr': self.config.sample_rate
            }
        
        return extractors
    
    def extract_features(self, audio: np.ndarray) -> Dict[str, np.ndarray]:
        """
        Extract comprehensive audio features.
        
        Args:
            audio: Audio signal array
            
        Returns:
            Dict[str, np.ndarray]: Extracted features
        """
        features = {}
        
        # Normalize audio if required
        if self.config.normalize_audio:
            audio = librosa.util.normalize(audio)
        
        # Apply pre-emphasis filter
        if self.config.pre_emphasis > 0:
            audio = librosa.effects.preemphasis(audio, coef=self.config.pre_emphasis)
        
        # Extract mel-spectrogram
        if 'mel_spectrogram' in self.feature_extractors:
            mel_spec = librosa.feature.melspectrogram(
                y=audio,
                sr=self.config.sample_rate,
                n_fft=self.config.n_fft,
                hop_length=self.config.hop_length,
                n_mels=self.config.n_mels
            )
            features['mel_spectrogram'] = librosa.power_to_db(mel_spec, ref=np.max)
        
        # Extract MFCC features
        if 'mfcc' in self.feature_extractors:
            mfcc = librosa.feature.mfcc(
                y=audio,
                sr=self.config.sample_rate,
                n_mfcc=self.config.n_mfcc,
                n_fft=self.config.n_fft,
                hop_length=self.config.hop_length
            )
            features['mfcc'] = mfcc
        
        # Extract chromagram
        if 'chromagram' in self.feature_extractors:
            chroma = librosa.feature.chroma_stft(
                y=audio,
                sr=self.config.sample_rate,
                hop_length=self.config.hop_length
            )
            features['chromagram'] = chroma
        
        # Extract spectral features
        if self.config.use_spectral_centroid:
            spectral_centroid = librosa.feature.spectral_centroid(
                y=audio,
                sr=self.config.sample_rate,
                hop_length=self.config.hop_length
            )
            features['spectral_centroid'] = spectral_centroid
        
        # Extract zero crossing rate
        if self.config.use_zero_crossing_rate:
            zcr = librosa.feature.zero_crossing_rate(
                audio,
                hop_length=self.config.hop_length
            )
            features['zero_crossing_rate'] = zcr
        
        # Extract tempo
        if self.config.use_tempo:
            tempo, beats = librosa.beat.beat_track(
                y=audio,
                sr=self.config.sample_rate,
                hop_length=self.config.hop_length
            )
            features['tempo'] = np.array([tempo])
            features['beats'] = beats
        
        return features
    
    def augment_audio(self, audio: np.ndarray) -> np.ndarray:
        """
        Apply audio augmentation techniques.
        
        Args:
            audio: Original audio signal
            
        Returns:
            np.ndarray: Augmented audio signal
        """
        augmented = audio.copy()
        
        # Time stretching
        if self.config.time_stretch:
            stretch_factor = np.random.uniform(0.8, 1.2)
            augmented = librosa.effects.time_stretch(augmented, rate=stretch_factor)
        
        # Pitch shifting
        if self.config.pitch_shift:
            pitch_shift_steps = np.random.uniform(-2, 2)
            augmented = librosa.effects.pitch_shift(
                augmented,
                sr=self.config.sample_rate,
                n_steps=pitch_shift_steps
            )
        
        # Add noise
        if self.config.add_noise:
            noise_factor = np.random.uniform(0.001, 0.01)
            noise = np.random.normal(0, noise_factor, augmented.shape)
            augmented = augmented + noise
        
        # Dynamic range compression
        if self.config.dynamic_range_compression:
            # Apply simple compression
            threshold = 0.5
            ratio = 4.0
            compressed = np.where(
                np.abs(augmented) > threshold,
                np.sign(augmented) * (threshold + (np.abs(augmented) - threshold) / ratio),
                augmented
            )
            augmented = compressed
        
        return augmented


class SpectralConvNet(BaseNeuralNetwork):
    """
    Spectral Convolutional Neural Network for audio processing.
    
    Specialized CNN architecture optimized for spectral analysis
    of audio signals, particularly effective for music classification
    and audio pattern recognition.
    """
    
    def __init__(self, config: Union[AudioConfig, Dict[str, Any]], name: str = None):
        if isinstance(config, dict):
            config = AudioConfig(**config)
        
        super().__init__(config, name or "SpectralConvNet")
        self.preprocessor = AudioPreprocessor(config)
        
    def build_model(self):
        """Build the spectral convolutional neural network."""
        if self.config.framework == "tensorflow":
            return self._build_tensorflow_model()
        elif self.config.framework == "pytorch":
            return self._build_pytorch_model()
        else:
            raise ValueError(f"Unsupported framework: {self.config.framework}")
    
    def _build_tensorflow_model(self):
        """Build TensorFlow spectral CNN model."""
        inputs = tf.keras.layers.Input(shape=self.config.input_shape)
        
        # Spectral convolution layers
        x = tf.keras.layers.Conv2D(32, (3, 3), activation='relu', padding='same')(inputs)
        x = tf.keras.layers.BatchNormalization()(x)
        x = tf.keras.layers.MaxPooling2D((2, 2))(x)
        x = tf.keras.layers.Dropout(0.25)(x)
        
        x = tf.keras.layers.Conv2D(64, (3, 3), activation='relu', padding='same')(x)
        x = tf.keras.layers.BatchNormalization()(x)
        x = tf.keras.layers.MaxPooling2D((2, 2))(x)
        x = tf.keras.layers.Dropout(0.25)(x)
        
        x = tf.keras.layers.Conv2D(128, (3, 3), activation='relu', padding='same')(x)
        x = tf.keras.layers.BatchNormalization()(x)
        x = tf.keras.layers.MaxPooling2D((2, 2))(x)
        x = tf.keras.layers.Dropout(0.25)(x)
        
        # Frequency-aware attention mechanism
        attention = tf.keras.layers.Conv2D(1, (1, 1), activation='sigmoid')(x)
        x = tf.keras.layers.Multiply()([x, attention])
        
        # Global average pooling to handle variable input sizes
        x = tf.keras.layers.GlobalAveragePooling2D()(x)
        
        # Dense layers
        x = tf.keras.layers.Dense(256, activation='relu')(x)
        x = tf.keras.layers.BatchNormalization()(x)
        x = tf.keras.layers.Dropout(self.config.dropout_rate)(x)
        
        x = tf.keras.layers.Dense(128, activation='relu')(x)
        x = tf.keras.layers.Dropout(self.config.dropout_rate)(x)
        
        # Output layer
        outputs = tf.keras.layers.Dense(
            self.config.output_shape[0],
            activation=self.config.output_activation
        )(x)
        
        model = tf.keras.Model(inputs=inputs, outputs=outputs)
        self.model = model
        return model
    
    def _build_pytorch_model(self):
        """Build PyTorch spectral CNN model."""
        class SpectralCNN(nn.Module):
            def __init__(self, config):
                super(SpectralCNN, self).__init__()
                self.config = config
                
                # Spectral convolution layers
                self.conv1 = nn.Conv2d(1, 32, kernel_size=3, padding=1)
                self.bn1 = nn.BatchNorm2d(32)
                self.conv2 = nn.Conv2d(32, 64, kernel_size=3, padding=1)
                self.bn2 = nn.BatchNorm2d(64)
                self.conv3 = nn.Conv2d(64, 128, kernel_size=3, padding=1)
                self.bn3 = nn.BatchNorm2d(128)
                
                # Attention mechanism
                self.attention = nn.Conv2d(128, 1, kernel_size=1)
                
                # Adaptive pooling for variable input sizes
                self.adaptive_pool = nn.AdaptiveAvgPool2d((1, 1))
                
                # Dense layers
                self.fc1 = nn.Linear(128, 256)
                self.bn_fc1 = nn.BatchNorm1d(256)
                self.fc2 = nn.Linear(256, 128)
                self.fc3 = nn.Linear(128, config.output_shape[0])
                
                self.dropout = nn.Dropout(config.dropout_rate)
                self.pool = nn.MaxPool2d(2, 2)
                
            def forward(self, x):
                # Spectral convolutions
                x = self.pool(F.relu(self.bn1(self.conv1(x))))
                x = F.dropout(x, 0.25, training=self.training)
                
                x = self.pool(F.relu(self.bn2(self.conv2(x))))
                x = F.dropout(x, 0.25, training=self.training)
                
                x = self.pool(F.relu(self.bn3(self.conv3(x))))
                x = F.dropout(x, 0.25, training=self.training)
                
                # Attention mechanism
                attention_weights = torch.sigmoid(self.attention(x))
                x = x * attention_weights
                
                # Global average pooling
                x = self.adaptive_pool(x)
                x = x.view(x.size(0), -1)
                
                # Dense layers
                x = F.relu(self.bn_fc1(self.fc1(x)))
                x = self.dropout(x)
                x = F.relu(self.fc2(x))
                x = self.dropout(x)
                x = self.fc3(x)
                
                return x
        
        model = SpectralCNN(self.config)
        self.model = model.to(self.device)
        return model
    
    def compile_model(self):
        """Compile the spectral CNN model."""
        if self.config.framework == "tensorflow":
            optimizer = tf.keras.optimizers.Adam(learning_rate=self.config.learning_rate)
            self.model.compile(
                optimizer=optimizer,
                loss=self.config.loss_function,
                metrics=['accuracy', 'precision', 'recall']
            )
        elif self.config.framework == "pytorch":
            self.optimizer = optim.Adam(
                self.model.parameters(),
                lr=self.config.learning_rate
            )
            self.loss_function = nn.CrossEntropyLoss()
    
    def train(self, train_data, validation_data=None, epochs=None, batch_size=None, callbacks=None):
        """Train the spectral CNN model."""
        epochs = epochs or self.config.epochs
        batch_size = batch_size or self.config.batch_size
        
        if self.config.framework == "tensorflow":
            return self._train_tensorflow(train_data, validation_data, epochs, batch_size, callbacks)
        elif self.config.framework == "pytorch":
            return self._train_pytorch(train_data, validation_data, epochs, batch_size)
    
    def _train_tensorflow(self, train_data, validation_data, epochs, batch_size, callbacks):
        """Train TensorFlow model."""
        start_time = time.time()
        
        history = self.model.fit(
            train_data,
            validation_data=validation_data,
            epochs=epochs,
            batch_size=batch_size,
            callbacks=callbacks,
            verbose=1
        )
        
        self.training_time = time.time() - start_time
        self.is_trained = True
        self.training_history.append(history.history)
        
        return history.history
    
    def _train_pytorch(self, train_data, validation_data, epochs, batch_size):
        """Train PyTorch model."""
        self.model.train()
        training_history = {'loss': [], 'accuracy': []}
        
        start_time = time.time()
        
        for epoch in range(epochs):
            epoch_loss = 0.0
            correct = 0
            total = 0
            
            for batch_idx, (data, target) in enumerate(train_data):
                data, target = data.to(self.device), target.to(self.device)
                
                self.optimizer.zero_grad()
                output = self.model(data)
                loss = self.loss_function(output, target)
                loss.backward()
                self.optimizer.step()
                
                epoch_loss += loss.item()
                _, predicted = torch.max(output.data, 1)
                total += target.size(0)
                correct += (predicted == target).sum().item()
            
            avg_loss = epoch_loss / len(train_data)
            accuracy = 100.0 * correct / total
            
            training_history['loss'].append(avg_loss)
            training_history['accuracy'].append(accuracy)
            
            if epoch % 10 == 0:
                logger.info(f'Epoch {epoch}: Loss: {avg_loss:.4f}, Accuracy: {accuracy:.2f}%')
        
        self.training_time = time.time() - start_time
        self.is_trained = True
        self.training_history.append(training_history)
        
        return training_history
    
    def predict(self, input_data, batch_size=None):
        """Make predictions with the spectral CNN."""
        if not self.is_trained:
            logger.warning("Model is not trained yet")
            return None
        
        start_time = time.time()
        
        if self.config.framework == "tensorflow":
            predictions = self.model.predict(input_data, batch_size=batch_size)
        elif self.config.framework == "pytorch":
            self.model.eval()
            with torch.no_grad():
                if isinstance(input_data, np.ndarray):
                    input_data = torch.from_numpy(input_data).float().to(self.device)
                predictions = self.model(input_data).cpu().numpy()
        
        inference_time = time.time() - start_time
        self.inference_times.append(inference_time)
        
        return predictions
    
    def evaluate(self, test_data, test_labels=None):
        """Evaluate the spectral CNN model."""
        if not self.is_trained:
            logger.warning("Model is not trained yet")
            return {}
        
        if self.config.framework == "tensorflow":
            if test_labels is not None:
                results = self.model.evaluate(test_data, test_labels, verbose=0)
                return dict(zip(self.model.metrics_names, results))
            else:
                return self.model.evaluate(test_data, verbose=0)
        
        elif self.config.framework == "pytorch":
            self.model.eval()
            total_loss = 0.0
            correct = 0
            total = 0
            
            with torch.no_grad():
                for data, target in test_data:
                    data, target = data.to(self.device), target.to(self.device)
                    output = self.model(data)
                    loss = self.loss_function(output, target)
                    total_loss += loss.item()
                    
                    _, predicted = torch.max(output.data, 1)
                    total += target.size(0)
                    correct += (predicted == target).sum().item()
            
            return {
                'loss': total_loss / len(test_data),
                'accuracy': 100.0 * correct / total
            }


class TemporalAudioNet(BaseNeuralNetwork):
    """
    Temporal Audio Neural Network for sequence modeling.
    
    Specialized architecture for processing temporal audio sequences
    using RNNs, LSTMs, and attention mechanisms for tasks like
    music sequence modeling and audio event detection.
    """
    
    def __init__(self, config: Union[AudioConfig, Dict[str, Any]], name: str = None):
        if isinstance(config, dict):
            config = AudioConfig(**config)
        
        super().__init__(config, name or "TemporalAudioNet")
        self.preprocessor = AudioPreprocessor(config)
        
    def build_model(self):
        """Build the temporal audio neural network."""
        if self.config.framework == "tensorflow":
            return self._build_tensorflow_model()
        elif self.config.framework == "pytorch":
            return self._build_pytorch_model()
        else:
            raise ValueError(f"Unsupported framework: {self.config.framework}")
    
    def _build_tensorflow_model(self):
        """Build TensorFlow temporal audio model."""
        inputs = tf.keras.layers.Input(shape=self.config.input_shape)
        
        # Bidirectional LSTM layers
        x = tf.keras.layers.Bidirectional(
            tf.keras.layers.LSTM(128, return_sequences=True, dropout=0.3)
        )(inputs)
        x = tf.keras.layers.BatchNormalization()(x)
        
        x = tf.keras.layers.Bidirectional(
            tf.keras.layers.LSTM(64, return_sequences=True, dropout=0.3)
        )(x)
        x = tf.keras.layers.BatchNormalization()(x)
        
        # Attention mechanism
        attention = tf.keras.layers.Dense(1, activation='tanh')(x)
        attention = tf.keras.layers.Softmax(axis=1)(attention)
        x = tf.keras.layers.Multiply()([x, attention])
        
        # Global average pooling
        x = tf.keras.layers.GlobalAveragePooling1D()(x)
        
        # Dense layers
        x = tf.keras.layers.Dense(256, activation='relu')(x)
        x = tf.keras.layers.BatchNormalization()(x)
        x = tf.keras.layers.Dropout(self.config.dropout_rate)(x)
        
        x = tf.keras.layers.Dense(128, activation='relu')(x)
        x = tf.keras.layers.Dropout(self.config.dropout_rate)(x)
        
        # Output layer
        outputs = tf.keras.layers.Dense(
            self.config.output_shape[0],
            activation=self.config.output_activation
        )(x)
        
        model = tf.keras.Model(inputs=inputs, outputs=outputs)
        self.model = model
        return model
    
    def _build_pytorch_model(self):
        """Build PyTorch temporal audio model."""
        class TemporalAudioModel(nn.Module):
            def __init__(self, config):
                super(TemporalAudioModel, self).__init__()
                self.config = config
                
                # LSTM layers
                self.lstm1 = nn.LSTM(
                    config.input_shape[-1], 128,
                    batch_first=True, bidirectional=True, dropout=0.3
                )
                self.bn1 = nn.BatchNorm1d(256)  # 128 * 2 for bidirectional
                
                self.lstm2 = nn.LSTM(
                    256, 64,
                    batch_first=True, bidirectional=True, dropout=0.3
                )
                self.bn2 = nn.BatchNorm1d(128)  # 64 * 2 for bidirectional
                
                # Attention mechanism
                self.attention = nn.Linear(128, 1)
                
                # Dense layers
                self.fc1 = nn.Linear(128, 256)
                self.bn_fc1 = nn.BatchNorm1d(256)
                self.fc2 = nn.Linear(256, 128)
                self.fc3 = nn.Linear(128, config.output_shape[0])
                
                self.dropout = nn.Dropout(config.dropout_rate)
                
            def forward(self, x):
                # LSTM layers
                x, _ = self.lstm1(x)
                x = self.bn1(x.transpose(1, 2)).transpose(1, 2)
                
                x, _ = self.lstm2(x)
                x = self.bn2(x.transpose(1, 2)).transpose(1, 2)
                
                # Attention mechanism
                attention_weights = torch.tanh(self.attention(x))
                attention_weights = F.softmax(attention_weights, dim=1)
                x = x * attention_weights
                
                # Global average pooling
                x = torch.mean(x, dim=1)
                
                # Dense layers
                x = F.relu(self.bn_fc1(self.fc1(x)))
                x = self.dropout(x)
                x = F.relu(self.fc2(x))
                x = self.dropout(x)
                x = self.fc3(x)
                
                return x
        
        model = TemporalAudioModel(self.config)
        self.model = model.to(self.device)
        return model
    
    def compile_model(self):
        """Compile the temporal audio model."""
        if self.config.framework == "tensorflow":
            optimizer = tf.keras.optimizers.Adam(learning_rate=self.config.learning_rate)
            self.model.compile(
                optimizer=optimizer,
                loss=self.config.loss_function,
                metrics=['accuracy', 'precision', 'recall']
            )
        elif self.config.framework == "pytorch":
            self.optimizer = optim.Adam(
                self.model.parameters(),
                lr=self.config.learning_rate
            )
            self.loss_function = nn.CrossEntropyLoss()
    
    def train(self, train_data, validation_data=None, epochs=None, batch_size=None, callbacks=None):
        """Train the temporal audio model."""
        epochs = epochs or self.config.epochs
        batch_size = batch_size or self.config.batch_size
        
        if self.config.framework == "tensorflow":
            return self._train_tensorflow(train_data, validation_data, epochs, batch_size, callbacks)
        elif self.config.framework == "pytorch":
            return self._train_pytorch(train_data, validation_data, epochs, batch_size)
    
    def _train_tensorflow(self, train_data, validation_data, epochs, batch_size, callbacks):
        """Train TensorFlow model."""
        start_time = time.time()
        
        history = self.model.fit(
            train_data,
            validation_data=validation_data,
            epochs=epochs,
            batch_size=batch_size,
            callbacks=callbacks,
            verbose=1
        )
        
        self.training_time = time.time() - start_time
        self.is_trained = True
        self.training_history.append(history.history)
        
        return history.history
    
    def _train_pytorch(self, train_data, validation_data, epochs, batch_size):
        """Train PyTorch model."""
        self.model.train()
        training_history = {'loss': [], 'accuracy': []}
        
        start_time = time.time()
        
        for epoch in range(epochs):
            epoch_loss = 0.0
            correct = 0
            total = 0
            
            for batch_idx, (data, target) in enumerate(train_data):
                data, target = data.to(self.device), target.to(self.device)
                
                self.optimizer.zero_grad()
                output = self.model(data)
                loss = self.loss_function(output, target)
                loss.backward()
                self.optimizer.step()
                
                epoch_loss += loss.item()
                _, predicted = torch.max(output.data, 1)
                total += target.size(0)
                correct += (predicted == target).sum().item()
            
            avg_loss = epoch_loss / len(train_data)
            accuracy = 100.0 * correct / total
            
            training_history['loss'].append(avg_loss)
            training_history['accuracy'].append(accuracy)
            
            if epoch % 10 == 0:
                logger.info(f'Epoch {epoch}: Loss: {avg_loss:.4f}, Accuracy: {accuracy:.2f}%')
        
        self.training_time = time.time() - start_time
        self.is_trained = True
        self.training_history.append(training_history)
        
        return training_history
    
    def predict(self, input_data, batch_size=None):
        """Make predictions with the temporal audio model."""
        if not self.is_trained:
            logger.warning("Model is not trained yet")
            return None
        
        start_time = time.time()
        
        if self.config.framework == "tensorflow":
            predictions = self.model.predict(input_data, batch_size=batch_size)
        elif self.config.framework == "pytorch":
            self.model.eval()
            with torch.no_grad():
                if isinstance(input_data, np.ndarray):
                    input_data = torch.from_numpy(input_data).float().to(self.device)
                predictions = self.model(input_data).cpu().numpy()
        
        inference_time = time.time() - start_time
        self.inference_times.append(inference_time)
        
        return predictions
    
    def evaluate(self, test_data, test_labels=None):
        """Evaluate the temporal audio model."""
        if not self.is_trained:
            logger.warning("Model is not trained yet")
            return {}
        
        if self.config.framework == "tensorflow":
            if test_labels is not None:
                results = self.model.evaluate(test_data, test_labels, verbose=0)
                return dict(zip(self.model.metrics_names, results))
            else:
                return self.model.evaluate(test_data, verbose=0)
        
        elif self.config.framework == "pytorch":
            self.model.eval()
            total_loss = 0.0
            correct = 0
            total = 0
            
            with torch.no_grad():
                for data, target in test_data:
                    data, target = data.to(self.device), target.to(self.device)
                    output = self.model(data)
                    loss = self.loss_function(output, target)
                    total_loss += loss.item()
                    
                    _, predicted = torch.max(output.data, 1)
                    total += target.size(0)
                    correct += (predicted == target).sum().item()
            
            return {
                'loss': total_loss / len(test_data),
                'accuracy': 100.0 * correct / total
            }


class AudioDataset(Dataset):
    """
    PyTorch Dataset for audio data processing.
    
    Handles loading, preprocessing, and augmentation of audio data
    for training and evaluation of audio neural networks.
    """
    
    def __init__(
        self,
        audio_paths: List[str],
        labels: List[int],
        config: AudioConfig,
        transform=None,
        augment=False
    ):
        self.audio_paths = audio_paths
        self.labels = labels
        self.config = config
        self.transform = transform
        self.augment = augment
        self.preprocessor = AudioPreprocessor(config)
        
    def __len__(self):
        return len(self.audio_paths)
    
    def __getitem__(self, idx):
        audio_path = self.audio_paths[idx]
        label = self.labels[idx]
        
        # Load audio
        audio, sr = librosa.load(audio_path, sr=self.config.sample_rate)
        
        # Apply augmentation if enabled
        if self.augment:
            audio = self.preprocessor.augment_audio(audio)
        
        # Extract features
        features = self.preprocessor.extract_features(audio)
        
        # Use mel-spectrogram as primary feature
        if 'mel_spectrogram' in features:
            feature_data = features['mel_spectrogram']
        else:
            feature_data = features['mfcc']
        
        # Convert to tensor
        feature_tensor = torch.from_numpy(feature_data).float()
        
        # Add channel dimension if needed
        if len(feature_tensor.shape) == 2:
            feature_tensor = feature_tensor.unsqueeze(0)
        
        # Apply additional transforms
        if self.transform:
            feature_tensor = self.transform(feature_tensor)
        
        return feature_tensor, torch.tensor(label, dtype=torch.long)


# Factory functions for creating audio networks
def create_spectral_cnn(
    input_shape: Tuple[int, ...],
    num_classes: int,
    sample_rate: int = 22050,
    n_mels: int = 128
) -> SpectralConvNet:
    """Create a spectral CNN for audio classification."""
    config = AudioConfig(
        input_shape=input_shape,
        output_shape=(num_classes,),
        sample_rate=sample_rate,
        n_mels=n_mels,
        mel_scale=True,
        framework="tensorflow"
    )
    return SpectralConvNet(config)


def create_temporal_audio_net(
    sequence_length: int,
    feature_dim: int,
    num_classes: int,
    sample_rate: int = 22050
) -> TemporalAudioNet:
    """Create a temporal audio network for sequence modeling."""
    config = AudioConfig(
        input_shape=(sequence_length, feature_dim),
        output_shape=(num_classes,),
        sample_rate=sample_rate,
        framework="tensorflow"
    )
    return TemporalAudioNet(config)


# Audio utility functions
def load_audio_dataset(
    data_dir: str,
    config: AudioConfig,
    split_ratio: float = 0.8
) -> Tuple[AudioDataset, AudioDataset]:
    """
    Load and split audio dataset.
    
    Args:
        data_dir: Directory containing audio files
        config: Audio configuration
        split_ratio: Train/test split ratio
        
    Returns:
        Tuple[AudioDataset, AudioDataset]: Train and test datasets
    """
    from pathlib import Path
    
    audio_files = []
    labels = []
    
    # Scan directory for audio files
    audio_dir = Path(data_dir)
    for class_dir in audio_dir.iterdir():
        if class_dir.is_dir():
            class_label = int(class_dir.name) if class_dir.name.isdigit() else hash(class_dir.name) % 1000
            
            for audio_file in class_dir.glob("*.wav"):
                audio_files.append(str(audio_file))
                labels.append(class_label)
    
    # Split dataset
    from sklearn.model_selection import train_test_split
    
    train_files, test_files, train_labels, test_labels = train_test_split(
        audio_files, labels, train_size=split_ratio, random_state=42
    )
    
    # Create datasets
    train_dataset = AudioDataset(train_files, train_labels, config, augment=True)
    test_dataset = AudioDataset(test_files, test_labels, config, augment=False)
    
    return train_dataset, test_dataset


def extract_audio_embeddings(
    model: BaseNeuralNetwork,
    audio_data: np.ndarray,
    layer_name: str = None
) -> np.ndarray:
    """
    Extract audio embeddings from a trained model.
    
    Args:
        model: Trained audio neural network
        audio_data: Input audio data
        layer_name: Name of layer to extract embeddings from
        
    Returns:
        np.ndarray: Extracted embeddings
    """
    if not model.is_trained:
        raise ValueError("Model must be trained to extract embeddings")
    
    if model.config.framework == "tensorflow":
        if layer_name:
            # Extract from specific layer
            intermediate_model = tf.keras.Model(
                inputs=model.model.input,
                outputs=model.model.get_layer(layer_name).output
            )
            embeddings = intermediate_model.predict(audio_data)
        else:
            # Extract from second-to-last layer
            intermediate_model = tf.keras.Model(
                inputs=model.model.input,
                outputs=model.model.layers[-2].output
            )
            embeddings = intermediate_model.predict(audio_data)
    
    elif model.config.framework == "pytorch":
        model.model.eval()
        embeddings = []
        
        def hook_fn(module, input, output):
            embeddings.append(output.detach().cpu().numpy())
        
        # Register hook on desired layer
        if layer_name:
            layer = dict(model.model.named_modules())[layer_name]
        else:
            layer = list(model.model.children())[-2]  # Second-to-last layer
        
        hook = layer.register_forward_hook(hook_fn)
        
        with torch.no_grad():
            if isinstance(audio_data, np.ndarray):
                audio_data = torch.from_numpy(audio_data).float().to(model.device)
            _ = model.model(audio_data)
        
        hook.remove()
        embeddings = embeddings[0] if embeddings else None
    
    return embeddings
