"""
Advanced Audio Feature Extraction Module

This module provides comprehensive audio signal processing and feature extraction
capabilities for the Spotify AI Agent, including spectral, temporal, harmonic,
and rhythmic feature analysis.
"""

import asyncio
import numpy as np
import librosa
import tensorflow as tf
from typing import Dict, List, Optional, Union, Tuple, Any
from dataclasses import dataclass
from abc import ABC, abstractmethod
import logging
from scipy import signal
from scipy.stats import kurtosis, skew
import warnings

warnings.filterwarnings('ignore')

logger = logging.getLogger(__name__)


@dataclass
class AudioConfig:
    """Configuration for audio processing"""
    sample_rate: int = 22050
    hop_length: int = 512
    n_fft: int = 2048
    n_mfcc: int = 13
    n_chroma: int = 12
    n_mel: int = 128
    max_duration: float = 30.0
    

class BaseAudioExtractor(ABC):
    """Base class for audio feature extractors"""
    
    def __init__(self, config: Optional[AudioConfig] = None):
        self.config = config or AudioConfig()
        
    @abstractmethod
    async def extract_features(self, audio: np.ndarray) -> Dict[str, Any]:
        """Extract features from audio signal"""
        pass


class SpectralFeatureExtractor(BaseAudioExtractor):
    """Advanced spectral feature extraction"""
    
    async def extract_features(self, audio: np.ndarray) -> Dict[str, Any]:
        """Extract comprehensive spectral features"""
        features = {}
        
        # Compute spectral features
        features.update(await self._extract_mfcc_features(audio))
        features.update(await self._extract_spectral_statistics(audio))
        features.update(await self._extract_mel_spectrogram_features(audio))
        features.update(await self._extract_spectral_contrast(audio))
        
        return features
    
    async def _extract_mfcc_features(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract MFCC features and derivatives"""
        mfccs = librosa.feature.mfcc(
            y=audio, 
            sr=self.config.sample_rate,
            n_mfcc=self.config.n_mfcc,
            hop_length=self.config.hop_length
        )
        
        # Delta and delta-delta features
        mfcc_delta = librosa.feature.delta(mfccs)
        mfcc_delta2 = librosa.feature.delta(mfccs, order=2)
        
        features = {}
        
        # MFCC statistics
        for i in range(self.config.n_mfcc):
            features[f'mfcc_{i}_mean'] = np.mean(mfccs[i])
            features[f'mfcc_{i}_std'] = np.std(mfccs[i])
            features[f'mfcc_{i}_skew'] = skew(mfccs[i])
            features[f'mfcc_{i}_kurtosis'] = kurtosis(mfccs[i])
            
            # Delta features
            features[f'mfcc_delta_{i}_mean'] = np.mean(mfcc_delta[i])
            features[f'mfcc_delta_{i}_std'] = np.std(mfcc_delta[i])
            
            # Delta-delta features
            features[f'mfcc_delta2_{i}_mean'] = np.mean(mfcc_delta2[i])
            features[f'mfcc_delta2_{i}_std'] = np.std(mfcc_delta2[i])
        
        return features
    
    async def _extract_spectral_statistics(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract spectral statistical features"""
        # Spectral centroid
        spectral_centroids = librosa.feature.spectral_centroid(
            y=audio, sr=self.config.sample_rate
        )[0]
        
        # Spectral rolloff
        spectral_rolloff = librosa.feature.spectral_rolloff(
            y=audio, sr=self.config.sample_rate
        )[0]
        
        # Spectral bandwidth
        spectral_bandwidth = librosa.feature.spectral_bandwidth(
            y=audio, sr=self.config.sample_rate
        )[0]
        
        # Zero crossing rate
        zcr = librosa.feature.zero_crossing_rate(audio)[0]
        
        # Spectral flatness
        spectral_flatness = librosa.feature.spectral_flatness(y=audio)[0]
        
        return {
            'spectral_centroid_mean': np.mean(spectral_centroids),
            'spectral_centroid_std': np.std(spectral_centroids),
            'spectral_rolloff_mean': np.mean(spectral_rolloff),
            'spectral_rolloff_std': np.std(spectral_rolloff),
            'spectral_bandwidth_mean': np.mean(spectral_bandwidth),
            'spectral_bandwidth_std': np.std(spectral_bandwidth),
            'zcr_mean': np.mean(zcr),
            'zcr_std': np.std(zcr),
            'spectral_flatness_mean': np.mean(spectral_flatness),
            'spectral_flatness_std': np.std(spectral_flatness)
        }
    
    async def _extract_mel_spectrogram_features(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract mel-spectrogram based features"""
        mel_spec = librosa.feature.melspectrogram(
            y=audio,
            sr=self.config.sample_rate,
            n_mels=self.config.n_mel,
            hop_length=self.config.hop_length
        )
        
        # Log mel spectrogram
        log_mel_spec = librosa.power_to_db(mel_spec, ref=np.max)
        
        features = {}
        
        # Statistical measures across time frames
        features['mel_spec_mean'] = np.mean(log_mel_spec)
        features['mel_spec_std'] = np.std(log_mel_spec)
        features['mel_spec_skew'] = skew(log_mel_spec.flatten())
        features['mel_spec_kurtosis'] = kurtosis(log_mel_spec.flatten())
        
        # Spectral energy distribution
        spectral_energy = np.sum(mel_spec, axis=1)
        features['spectral_energy_variance'] = np.var(spectral_energy)
        features['spectral_energy_concentration'] = np.max(spectral_energy) / np.sum(spectral_energy)
        
        return features
    
    async def _extract_spectral_contrast(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract spectral contrast features"""
        spectral_contrast = librosa.feature.spectral_contrast(
            y=audio, sr=self.config.sample_rate
        )
        
        features = {}
        for i in range(spectral_contrast.shape[0]):
            features[f'spectral_contrast_{i}_mean'] = np.mean(spectral_contrast[i])
            features[f'spectral_contrast_{i}_std'] = np.std(spectral_contrast[i])
        
        return features


class RhythmFeatureExtractor(BaseAudioExtractor):
    """Advanced rhythm and tempo feature extraction"""
    
    async def extract_features(self, audio: np.ndarray) -> Dict[str, Any]:
        """Extract comprehensive rhythm features"""
        features = {}
        
        features.update(await self._extract_tempo_features(audio))
        features.update(await self._extract_onset_features(audio))
        features.update(await self._extract_beat_features(audio))
        features.update(await self._extract_rhythm_patterns(audio))
        
        return features
    
    async def _extract_tempo_features(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract tempo-related features"""
        # Estimate tempo
        onset_envelope = librosa.onset.onset_strength(y=audio, sr=self.config.sample_rate)
        tempo, beats = librosa.beat.beat_track(
            onset_envelope=onset_envelope,
            sr=self.config.sample_rate
        )
        
        # Tempo variation
        tempo_dynamic = librosa.beat.tempo(
            onset_envelope=onset_envelope,
            sr=self.config.sample_rate,
            aggregate=None
        )
        
        return {
            'tempo_bpm': float(tempo),
            'tempo_stability': 1.0 / (1.0 + np.std(tempo_dynamic)),
            'tempo_variation': np.std(tempo_dynamic),
            'beat_strength': np.mean(onset_envelope[beats])
        }
    
    async def _extract_onset_features(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract onset detection features"""
        onset_frames = librosa.onset.onset_detect(
            y=audio,
            sr=self.config.sample_rate,
            hop_length=self.config.hop_length
        )
        
        onset_times = librosa.frames_to_time(
            onset_frames,
            sr=self.config.sample_rate,
            hop_length=self.config.hop_length
        )
        
        if len(onset_times) > 1:
            onset_intervals = np.diff(onset_times)
            onset_rate = len(onset_times) / (len(audio) / self.config.sample_rate)
            
            return {
                'onset_rate': onset_rate,
                'onset_regularity': 1.0 / (1.0 + np.std(onset_intervals)),
                'onset_density_variation': np.std(onset_intervals),
                'avg_onset_interval': np.mean(onset_intervals)
            }
        else:
            return {
                'onset_rate': 0.0,
                'onset_regularity': 0.0,
                'onset_density_variation': 0.0,
                'avg_onset_interval': 0.0
            }
    
    async def _extract_beat_features(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract beat-related features"""
        # Beat tracking
        _, beats = librosa.beat.beat_track(y=audio, sr=self.config.sample_rate)
        
        if len(beats) > 2:
            beat_times = librosa.frames_to_time(beats, sr=self.config.sample_rate)
            beat_intervals = np.diff(beat_times)
            
            return {
                'beat_consistency': 1.0 / (1.0 + np.std(beat_intervals)),
                'beat_strength_variation': np.std(beat_intervals),
                'rhythmic_regularity': np.exp(-np.var(beat_intervals))
            }
        else:
            return {
                'beat_consistency': 0.0,
                'beat_strength_variation': 0.0,
                'rhythmic_regularity': 0.0
            }
    
    async def _extract_rhythm_patterns(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract rhythmic pattern features"""
        # Tempogram for rhythm analysis
        hop_length = self.config.hop_length
        oenv = librosa.onset.onset_strength(y=audio, sr=self.config.sample_rate)
        tempogram = librosa.feature.tempogram(
            onset_envelope=oenv,
            sr=self.config.sample_rate,
            hop_length=hop_length
        )
        
        # Rhythm complexity
        rhythm_complexity = np.std(tempogram.flatten())
        rhythm_periodicity = np.max(np.mean(tempogram, axis=1))
        
        return {
            'rhythm_complexity': rhythm_complexity,
            'rhythm_periodicity': rhythm_periodicity,
            'rhythmic_energy': np.mean(tempogram),
            'rhythmic_stability': 1.0 / (1.0 + np.std(tempogram, axis=1).mean())
        }


class HarmonicFeatureExtractor(BaseAudioExtractor):
    """Advanced harmonic and tonal feature extraction"""
    
    async def extract_features(self, audio: np.ndarray) -> Dict[str, Any]:
        """Extract comprehensive harmonic features"""
        features = {}
        
        features.update(await self._extract_chroma_features(audio))
        features.update(await self._extract_tonnetz_features(audio))
        features.update(await self._extract_harmonic_percussive(audio))
        features.update(await self._extract_pitch_features(audio))
        
        return features
    
    async def _extract_chroma_features(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract chromagram features"""
        chroma = librosa.feature.chroma_stft(
            y=audio,
            sr=self.config.sample_rate,
            n_chroma=self.config.n_chroma
        )
        
        features = {}
        
        # Chroma statistics
        for i in range(self.config.n_chroma):
            features[f'chroma_{i}_mean'] = np.mean(chroma[i])
            features[f'chroma_{i}_std'] = np.std(chroma[i])
        
        # Harmonic change detection
        chroma_diff = np.diff(chroma, axis=1)
        features['harmonic_change_rate'] = np.mean(np.abs(chroma_diff))
        
        # Key strength
        features['key_strength'] = np.max(np.mean(chroma, axis=1))
        features['tonal_clarity'] = np.std(np.mean(chroma, axis=1))
        
        return features
    
    async def _extract_tonnetz_features(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract tonnetz (tonal centroid) features"""
        tonnetz = librosa.feature.tonnetz(y=audio, sr=self.config.sample_rate)
        
        features = {}
        for i in range(tonnetz.shape[0]):
            features[f'tonnetz_{i}_mean'] = np.mean(tonnetz[i])
            features[f'tonnetz_{i}_std'] = np.std(tonnetz[i])
        
        # Tonal complexity
        features['tonal_complexity'] = np.mean(np.std(tonnetz, axis=1))
        features['harmonic_stability'] = 1.0 / (1.0 + np.mean(np.std(tonnetz, axis=1)))
        
        return features
    
    async def _extract_harmonic_percussive(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract harmonic vs percussive content features"""
        # Harmonic-percussive separation
        harmonic, percussive = librosa.effects.hpss(audio)
        
        # Energy ratio
        harmonic_energy = np.sum(harmonic ** 2)
        percussive_energy = np.sum(percussive ** 2)
        total_energy = harmonic_energy + percussive_energy
        
        if total_energy > 0:
            harmonic_ratio = harmonic_energy / total_energy
            percussive_ratio = percussive_energy / total_energy
        else:
            harmonic_ratio = percussive_ratio = 0.0
        
        return {
            'harmonic_ratio': harmonic_ratio,
            'percussive_ratio': percussive_ratio,
            'harmonic_percussive_balance': abs(harmonic_ratio - percussive_ratio),
            'harmonic_energy': harmonic_energy,
            'percussive_energy': percussive_energy
        }
    
    async def _extract_pitch_features(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract pitch-related features"""
        # Pitch tracking using fundamental frequency estimation
        f0, _, _ = librosa.pyin(
            audio,
            fmin=librosa.note_to_hz('C2'),
            fmax=librosa.note_to_hz('C7'),
            sr=self.config.sample_rate
        )
        
        # Remove NaN values
        f0_clean = f0[~np.isnan(f0)]
        
        if len(f0_clean) > 0:
            return {
                'pitch_mean': np.mean(f0_clean),
                'pitch_std': np.std(f0_clean),
                'pitch_range': np.max(f0_clean) - np.min(f0_clean),
                'pitch_stability': 1.0 / (1.0 + np.std(f0_clean) / np.mean(f0_clean)),
                'voiced_ratio': len(f0_clean) / len(f0)
            }
        else:
            return {
                'pitch_mean': 0.0,
                'pitch_std': 0.0,
                'pitch_range': 0.0,
                'pitch_stability': 0.0,
                'voiced_ratio': 0.0
            }


class TemporalFeatureExtractor(BaseAudioExtractor):
    """Advanced temporal feature extraction"""
    
    async def extract_features(self, audio: np.ndarray) -> Dict[str, Any]:
        """Extract comprehensive temporal features"""
        features = {}
        
        features.update(await self._extract_energy_features(audio))
        features.update(await self._extract_dynamic_features(audio))
        features.update(await self._extract_texture_features(audio))
        features.update(await self._extract_envelope_features(audio))
        
        return features
    
    async def _extract_energy_features(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract energy-based temporal features"""
        # RMS energy
        rms = librosa.feature.rms(y=audio, hop_length=self.config.hop_length)[0]
        
        # Short-time energy
        frame_length = self.config.hop_length * 2
        energy = np.array([
            np.sum(audio[i:i+frame_length]**2) 
            for i in range(0, len(audio)-frame_length, self.config.hop_length)
        ])
        
        return {
            'rms_mean': np.mean(rms),
            'rms_std': np.std(rms),
            'energy_mean': np.mean(energy),
            'energy_std': np.std(energy),
            'energy_variation': np.var(energy) / (np.mean(energy) + 1e-8),
            'dynamic_range': (np.max(rms) - np.min(rms)) / (np.max(rms) + 1e-8)
        }
    
    async def _extract_dynamic_features(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract dynamic range and loudness features"""
        # Peak-to-average ratio
        peak_amplitude = np.max(np.abs(audio))
        avg_amplitude = np.mean(np.abs(audio))
        
        if avg_amplitude > 0:
            peak_to_avg_ratio = peak_amplitude / avg_amplitude
        else:
            peak_to_avg_ratio = 0.0
        
        # Crest factor
        rms_value = np.sqrt(np.mean(audio**2))
        if rms_value > 0:
            crest_factor = peak_amplitude / rms_value
        else:
            crest_factor = 0.0
        
        return {
            'peak_to_avg_ratio': peak_to_avg_ratio,
            'crest_factor': crest_factor,
            'signal_energy': np.sum(audio**2),
            'amplitude_variance': np.var(np.abs(audio))
        }
    
    async def _extract_texture_features(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract audio texture features"""
        # Spectral rolloff variation over time
        rolloff = librosa.feature.spectral_rolloff(y=audio, sr=self.config.sample_rate)[0]
        
        # Spectral flux (measure of spectral change)
        stft = librosa.stft(audio, hop_length=self.config.hop_length)
        magnitude = np.abs(stft)
        spectral_flux = np.mean(np.diff(magnitude, axis=1)**2)
        
        return {
            'spectral_rolloff_variation': np.std(rolloff),
            'spectral_flux': spectral_flux,
            'texture_roughness': np.mean(np.abs(np.diff(audio))),
            'spectral_novelty': np.mean(np.abs(np.diff(magnitude, axis=1)))
        }
    
    async def _extract_envelope_features(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract envelope-based features"""
        # Amplitude envelope
        envelope = np.abs(signal.hilbert(audio))
        
        # Attack time (simplified)
        attack_samples = np.argmax(envelope)
        attack_time = attack_samples / self.config.sample_rate
        
        # Decay characteristics
        peak_idx = np.argmax(envelope)
        if peak_idx < len(envelope) - 1:
            decay_env = envelope[peak_idx:]
            decay_rate = -np.gradient(decay_env).mean()
        else:
            decay_rate = 0.0
        
        return {
            'envelope_attack_time': attack_time,
            'envelope_decay_rate': decay_rate,
            'envelope_sustain_level': np.mean(envelope[len(envelope)//2:]),
            'envelope_variation': np.std(envelope)
        }


class AudioFeatureExtractor:
    """Main audio feature extractor orchestrating all sub-extractors"""
    
    def __init__(self, config: Optional[AudioConfig] = None):
        self.config = config or AudioConfig()
        
        # Initialize sub-extractors
        self.spectral_extractor = SpectralFeatureExtractor(self.config)
        self.rhythm_extractor = RhythmFeatureExtractor(self.config)
        self.harmonic_extractor = HarmonicFeatureExtractor(self.config)
        self.temporal_extractor = TemporalFeatureExtractor(self.config)
        
        logger.info("AudioFeatureExtractor initialized with comprehensive extractors")
    
    async def extract_from_file(self, file_path: str) -> Dict[str, float]:
        """Extract features from audio file"""
        try:
            # Load audio with librosa
            audio, sr = librosa.load(
                file_path,
                sr=self.config.sample_rate,
                duration=self.config.max_duration
            )
            
            return await self.extract_from_array(audio)
            
        except Exception as e:
            logger.error(f"Error extracting features from file {file_path}: {e}")
            raise
    
    async def extract_from_bytes(self, audio_data: bytes) -> Dict[str, float]:
        """Extract features from audio bytes"""
        try:
            # Convert bytes to numpy array (implementation depends on format)
            # This is a placeholder - actual implementation would depend on audio format
            import io
            import soundfile as sf
            
            audio, sr = sf.read(io.BytesIO(audio_data))
            
            # Resample if necessary
            if sr != self.config.sample_rate:
                audio = librosa.resample(audio, orig_sr=sr, target_sr=self.config.sample_rate)
            
            return await self.extract_from_array(audio)
            
        except Exception as e:
            logger.error(f"Error extracting features from bytes: {e}")
            raise
    
    async def extract_from_array(self, audio: np.ndarray) -> Dict[str, float]:
        """Extract comprehensive features from audio array"""
        try:
            # Normalize audio
            if np.max(np.abs(audio)) > 0:
                audio = audio / np.max(np.abs(audio))
            
            # Extract features from all extractors concurrently
            spectral_task = self.spectral_extractor.extract_features(audio)
            rhythm_task = self.rhythm_extractor.extract_features(audio)
            harmonic_task = self.harmonic_extractor.extract_features(audio)
            temporal_task = self.temporal_extractor.extract_features(audio)
            
            # Wait for all extractions to complete
            spectral_features, rhythm_features, harmonic_features, temporal_features = await asyncio.gather(
                spectral_task, rhythm_task, harmonic_task, temporal_task
            )
            
            # Combine all features
            all_features = {
                **spectral_features,
                **rhythm_features,
                **harmonic_features,
                **temporal_features
            }
            
            # Add metadata
            all_features['audio_duration'] = len(audio) / self.config.sample_rate
            all_features['feature_extraction_version'] = "2.0.0"
            
            logger.info(f"Extracted {len(all_features)} audio features successfully")
            return all_features
            
        except Exception as e:
            logger.error(f"Error extracting features from audio array: {e}")
            raise
    
    async def extract_batch(self, audio_files: List[str]) -> List[Dict[str, float]]:
        """Extract features from multiple audio files"""
        tasks = [self.extract_from_file(file_path) for file_path in audio_files]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        
        features_list = []
        for i, result in enumerate(results):
            if isinstance(result, Exception):
                logger.error(f"Failed to extract features from {audio_files[i]}: {result}")
                features_list.append({})
            else:
                features_list.append(result)
        
        return features_list


# Export main classes
__all__ = [
    'AudioFeatureExtractor',
    'SpectralFeatureExtractor',
    'RhythmFeatureExtractor', 
    'HarmonicFeatureExtractor',
    'TemporalFeatureExtractor',
    'AudioConfig'
]
