logger = logging.getLogger(__name__)


class AnalysisType(Enum):
    """Types of analysis"""
    ANOMALY_DETECTION = "anomaly_detection"
    TREND_ANALYSIS = "trend_analysis"
    PERFORMANCE_ANALYSIS = "performance_analysis"
    PREDICTIVE_ANALYSIS = "predictive_analysis"
    ROOT_CAUSE_ANALYSIS = "root_cause_analysis"
    CAPACITY_PLANNING = "capacity_planning"


class AnomalyType(Enum):
    """Types of anomalies"""
    POINT_ANOMALY = "point"
    CONTEXTUAL_ANOMALY = "contextual"
    COLLECTIVE_ANOMALY = "collective"
    DRIFT_ANOMALY = "drift"


@dataclass
class AnalysisResult:
    """Result of an analysis operation"""
    analysis_type: AnalysisType
    timestamp: datetime
    metrics_analyzed: List[str]
    findings: List[Dict[str, Any]]
    confidence_score: float
    severity: str
    recommendations: List[str]
    metadata: Dict[str, Any] = field(default_factory=dict)


class BaseAnalyzer(ABC):
    """Base class for all analyzers"""
    
    def __init__(self, name: str, config: MonitoringConfig):
        self.name = name
        self.config = config
        self.is_enabled = True
        
        # Analysis history
        self.analysis_history: List[AnalysisResult] = []
        self.baseline_data: Dict[str, Any] = {}
        
        # Performance tracking
        self.analysis_count = 0
        self.total_analysis_time = 0.0
        self.error_count = 0
        
        # Setup logging
        self.logger = logging.getLogger(f"{__name__}.{self.__class__.__name__}")
    
    @abstractmethod
    async def analyze(self, metrics_data: Dict[str, Any]) -> AnalysisResult:
        """Analyze metrics data - to be implemented by subclasses"""
        pass
    
    async def analyze_with_timing(self, metrics_data: Dict[str, Any]) -> Dict[str, Any]:
        """Analyze with performance timing"""
        start_time = time.time()
        
        try:
            result = await self.analyze(metrics_data)
            self.analysis_count += 1
            
            # Update timing statistics
            analysis_time = time.time() - start_time
            self.total_analysis_time += analysis_time
            
            # Store in history
            self.analysis_history.append(result)
            
            # Keep only recent history
            if len(self.analysis_history) > 1000:
                self.analysis_history = self.analysis_history[-1000:]
            
            return {
                "result": result,
                "analysis_time": analysis_time,
                "analysis_count": self.analysis_count,
                "error_count": self.error_count
            }
            
        except Exception as e:
            self.error_count += 1
            self.logger.error(f"Error in analysis {self.name}: {e}")
            
            return {
                "result": None,
                "analysis_time": time.time() - start_time,
                "analysis_count": self.analysis_count,
                "error_count": self.error_count,
                "error": str(e)
            }
    
    def get_analyzer_stats(self) -> Dict[str, Any]:
        """Get statistics about this analyzer"""
        return {
            "name": self.name,
            "enabled": self.is_enabled,
            "analysis_count": self.analysis_count,
            "error_count": self.error_count,
            "average_analysis_time": (
                self.total_analysis_time / self.analysis_count 
                if self.analysis_count > 0 else 0.0
            ),
            "history_size": len(self.analysis_history)
        }


class AnomalyDetector(BaseAnalyzer):
    """
    Ultra-advanced anomaly detection system using multiple ML algorithms
    and statistical methods for comprehensive anomaly identification.
    """
    
    def __init__(self, config: MonitoringConfig):
        super().__init__("anomaly_detector", config)
        
        # ML models for anomaly detection
        self.models = {
            "isolation_forest": IsolationForest(
                contamination=1 - config.anomaly_threshold,
                random_state=42,
                n_estimators=100
            ),
            "dbscan": DBSCAN(eps=0.5, min_samples=5)
        }
        
        # Statistical thresholds
        self.statistical_thresholds = {
            "z_score": 3.0,
            "iqr_multiplier": 1.5,
            "percentile_bounds": (1, 99)
        }
        
        # Data preprocessing
        self.scaler = StandardScaler()
        self.feature_columns = []
        self.is_fitted = False
        
        # Anomaly tracking
        self.recent_anomalies: List[Dict[str, Any]] = []
        self.anomaly_patterns: Dict[str, List[Dict[str, Any]]] = {}
        
    async def analyze(self, metrics_data: Dict[str, Any]) -> AnalysisResult:
        """Detect anomalies in metrics data"""
        findings = []
        
        try:
            # Prepare data for analysis
            processed_data = await self._prepare_data(metrics_data)
            
            if processed_data is None or len(processed_data) == 0:
                return AnalysisResult(
                    analysis_type=AnalysisType.ANOMALY_DETECTION,
                    timestamp=datetime.utcnow(),
                    metrics_analyzed=[],
                    findings=[],
                    confidence_score=0.0,
                    severity="info",
                    recommendations=[]
                )
            
            # Statistical anomaly detection
            statistical_anomalies = await self._detect_statistical_anomalies(processed_data)
            findings.extend(statistical_anomalies)
            
            # ML-based anomaly detection
            if self.is_fitted or len(self.analysis_history) > 10:
                ml_anomalies = await self._detect_ml_anomalies(processed_data)
                findings.extend(ml_anomalies)
            
            # Pattern-based anomaly detection
            pattern_anomalies = await self._detect_pattern_anomalies(processed_data)
            findings.extend(pattern_anomalies)
            
            # Contextual anomaly detection
            contextual_anomalies = await self._detect_contextual_anomalies(processed_data)
            findings.extend(contextual_anomalies)
            
            # Calculate overall confidence and severity
            confidence_score = self._calculate_confidence(findings)
            severity = self._determine_severity(findings)
            
            # Generate recommendations
            recommendations = await self._generate_anomaly_recommendations(findings)
            
            # Update anomaly tracking
            await self._update_anomaly_tracking(findings)
            
            return AnalysisResult(
                analysis_type=AnalysisType.ANOMALY_DETECTION,
                timestamp=datetime.utcnow(),
                metrics_analyzed=list(processed_data.columns) if processed_data is not None else [],
                findings=findings,
                confidence_score=confidence_score,
                severity=severity,
                recommendations=recommendations,
                metadata={
                    "models_used": list(self.models.keys()),
                    "data_points_analyzed": len(processed_data) if processed_data is not None else 0,
                    "is_fitted": self.is_fitted
                }
            )
            
        except Exception as e:
            self.logger.error(f"Error in anomaly detection: {e}")
            raise
    
    async def _prepare_data(self, metrics_data: Dict[str, Any]) -> Optional[pd.DataFrame]:
        """Prepare metrics data for anomaly detection"""
        try:
            # Extract numerical metrics
            numerical_data = {}
            
            for source, data in metrics_data.items():
                if isinstance(data, dict) and "metrics" in data:
                    metrics = data["metrics"]
                    for metric_name, metric_value in self._flatten_metrics(metrics).items():
                        if isinstance(metric_value, (int, float)) and not math.isnan(metric_value):
                            column_name = f"{source}_{metric_name}"
                            numerical_data[column_name] = metric_value
            
            if not numerical_data:
                return None
            
            # Create DataFrame
            df = pd.DataFrame([numerical_data])
            
            # Handle missing columns (add with default values)
            for col in self.feature_columns:
                if col not in df.columns:
                    df[col] = 0.0
            
            # Ensure consistent column order
            if self.feature_columns:
                df = df.reindex(columns=self.feature_columns, fill_value=0.0)
            else:
                self.feature_columns = list(df.columns)
            
            return df
            
        except Exception as e:
            self.logger.error(f"Error preparing data for anomaly detection: {e}")
            return None
    
    def _flatten_metrics(self, metrics: Dict[str, Any], prefix: str = "") -> Dict[str, Any]:
        """Flatten nested metrics dictionary"""
        flattened = {}
        
        for key, value in metrics.items():
            new_key = f"{prefix}_{key}" if prefix else key
            
            if isinstance(value, dict):
                flattened.update(self._flatten_metrics(value, new_key))
            elif isinstance(value, (int, float)):
                flattened[new_key] = value
            elif isinstance(value, list) and len(value) > 0:
                # Take the first numerical value from lists
                for item in value:
                    if isinstance(item, (int, float)):
                        flattened[new_key] = item
                        break
        
        return flattened
    
    async def _detect_statistical_anomalies(self, data: pd.DataFrame) -> List[Dict[str, Any]]:
        """Detect anomalies using statistical methods"""
        anomalies = []
        
        try:
            for column in data.columns:
                values = data[column].values
                
                if len(values) == 0:
                    continue
                
                # Z-score based detection
                if len(self.analysis_history) > 5:
                    historical_values = self._get_historical_values(column)
                    if len(historical_values) > 10:
                        mean_val = np.mean(historical_values)
                        std_val = np.std(historical_values)
                        
                        if std_val > 0:
                            z_score = abs((values[0] - mean_val) / std_val)
                            
                            if z_score > self.statistical_thresholds["z_score"]:
                                anomalies.append({
                                    "type": AnomalyType.POINT_ANOMALY.value,
                                    "method": "z_score",
                                    "metric": column,
                                    "value": values[0],
                                    "expected_range": [
                                        mean_val - 2 * std_val,
                                        mean_val + 2 * std_val
                                    ],
                                    "deviation_score": z_score,
                                    "confidence": min(z_score / 5.0, 1.0),
                                    "description": f"Z-score anomaly detected for {column}"
                                })
                
                # IQR based detection
                if len(self.analysis_history) > 20:
                    historical_values = self._get_historical_values(column)
                    if len(historical_values) > 20:
                        q1 = np.percentile(historical_values, 25)
                        q3 = np.percentile(historical_values, 75)
                        iqr = q3 - q1
                        
                        lower_bound = q1 - self.statistical_thresholds["iqr_multiplier"] * iqr
                        upper_bound = q3 + self.statistical_thresholds["iqr_multiplier"] * iqr
                        
                        if values[0] < lower_bound or values[0] > upper_bound:
                            anomalies.append({
                                "type": AnomalyType.POINT_ANOMALY.value,
                                "method": "iqr",
                                "metric": column,
                                "value": values[0],
                                "expected_range": [lower_bound, upper_bound],
                                "confidence": 0.7,
                                "description": f"IQR outlier detected for {column}"
                            })
        
        except Exception as e:
            self.logger.error(f"Error in statistical anomaly detection: {e}")
        
        return anomalies
    
    async def _detect_ml_anomalies(self, data: pd.DataFrame) -> List[Dict[str, Any]]:
        """Detect anomalies using machine learning models"""
        anomalies = []
        
        try:
            # Prepare training data from history
            training_data = self._prepare_training_data()
            
            if training_data is None or len(training_data) < 10:
                return anomalies
            
            # Fit models if not already fitted
            if not self.is_fitted:
                await self._fit_models(training_data)
            
            # Scale the current data
            scaled_data = self.scaler.transform(data)
            
            # Isolation Forest detection
            if "isolation_forest" in self.models:
                try:
                    anomaly_score = self.models["isolation_forest"].decision_function(scaled_data)[0]
                    is_anomaly = self.models["isolation_forest"].predict(scaled_data)[0] == -1
                    
                    if is_anomaly:
                        anomalies.append({
                            "type": AnomalyType.POINT_ANOMALY.value,
                            "method": "isolation_forest",
                            "anomaly_score": float(anomaly_score),
                            "confidence": min(abs(anomaly_score) / 0.5, 1.0),
                            "description": "Isolation Forest detected anomaly in overall pattern"
                        })
                except Exception as e:
                    self.logger.debug(f"Isolation Forest error: {e}")
        
        except Exception as e:
            self.logger.error(f"Error in ML anomaly detection: {e}")
        
        return anomalies
    
    async def _detect_pattern_anomalies(self, data: pd.DataFrame) -> List[Dict[str, Any]]:
        """Detect pattern-based anomalies"""
        anomalies = []
        
        try:
            # Check for sudden spikes or drops
            for column in data.columns:
                historical_values = self._get_historical_values(column, limit=10)
                
                if len(historical_values) < 5:
                    continue
                
                current_value = data[column].iloc[0]
                recent_avg = np.mean(historical_values[-5:])
                
                # Check for sudden spike
                if current_value > recent_avg * 2 and recent_avg > 0:
                    anomalies.append({
                        "type": AnomalyType.POINT_ANOMALY.value,
                        "method": "spike_detection",
                        "metric": column,
                        "value": current_value,
                        "baseline": recent_avg,
                        "spike_ratio": current_value / recent_avg,
                        "confidence": 0.8,
                        "description": f"Sudden spike detected in {column}"
                    })
                
                # Check for sudden drop
                elif current_value < recent_avg * 0.5 and recent_avg > 0:
                    anomalies.append({
                        "type": AnomalyType.POINT_ANOMALY.value,
                        "method": "drop_detection",
                        "metric": column,
                        "value": current_value,
                        "baseline": recent_avg,
                        "drop_ratio": current_value / recent_avg,
                        "confidence": 0.8,
                        "description": f"Sudden drop detected in {column}"
                    })
        
        except Exception as e:
            self.logger.error(f"Error in pattern anomaly detection: {e}")
        
        return anomalies
    
    async def _detect_contextual_anomalies(self, data: pd.DataFrame) -> List[Dict[str, Any]]:
        """Detect contextual anomalies based on time and conditions"""
        anomalies = []
        
        try:
            current_time = datetime.utcnow()
            hour = current_time.hour
            day_of_week = current_time.weekday()
            
            # Business hours anomalies
            is_business_hours = 9 <= hour <= 17 and day_of_week < 5
            
            for column in data.columns:
                if "cpu" in column.lower() or "memory" in column.lower():
                    current_value = data[column].iloc[0]
                    
                    # High resource usage during business hours
                    if is_business_hours and current_value > 80:
                        anomalies.append({
                            "type": AnomalyType.CONTEXTUAL_ANOMALY.value,
                            "method": "business_hours_context",
                            "metric": column,
                            "value": current_value,
                            "context": "business_hours",
                            "confidence": 0.7,
                            "description": f"High {column} usage during business hours"
                        })
        
        except Exception as e:
            self.logger.error(f"Error in contextual anomaly detection: {e}")
        
        return anomalies
    
    def _get_historical_values(self, metric_name: str, limit: int = 100) -> List[float]:
        """Get historical values for a specific metric"""
        values = []
        
        for result in self.analysis_history[-limit:]:
            if hasattr(result, 'metadata') and 'historical_data' in result.metadata:
                historical_data = result.metadata['historical_data']
                if metric_name in historical_data:
                    values.append(historical_data[metric_name])
        
        return values
    
    def _prepare_training_data(self) -> Optional[pd.DataFrame]:
        """Prepare training data from historical analysis results"""
        try:
            # This would collect historical data for training
            # For now, return None to indicate no training data available
            return None
        except Exception as e:
            self.logger.error(f"Error preparing training data: {e}")
            return None
    
    async def _fit_models(self, training_data: pd.DataFrame):
        """Fit ML models with training data"""
        try:
            # Scale the training data
            scaled_data = self.scaler.fit_transform(training_data)
            
            # Fit Isolation Forest
            self.models["isolation_forest"].fit(scaled_data)
            
            self.is_fitted = True
            self.logger.info("Anomaly detection models fitted successfully")
            
        except Exception as e:
            self.logger.error(f"Error fitting models: {e}")
    
    def _calculate_confidence(self, findings: List[Dict[str, Any]]) -> float:
        """Calculate overall confidence score for anomaly findings"""
        if not findings:
            return 0.0
        
        confidences = [f.get("confidence", 0.5) for f in findings]
        return min(np.mean(confidences), 1.0)
    
    def _determine_severity(self, findings: List[Dict[str, Any]]) -> str:
        """Determine severity level based on findings"""
        if not findings:
            return "info"
        
        high_confidence_anomalies = [f for f in findings if f.get("confidence", 0) > 0.8]
        
        if len(high_confidence_anomalies) > 2:
            return "critical"
        elif len(high_confidence_anomalies) > 0:
            return "warning"
        elif len(findings) > 3:
            return "warning"
        else:
            return "info"
    
    async def _generate_anomaly_recommendations(self, findings: List[Dict[str, Any]]) -> List[str]:
        """Generate recommendations based on anomaly findings"""
        recommendations = []
        
        if not findings:
            return recommendations
        
        # Check for resource-related anomalies
        resource_anomalies = [f for f in findings if any(
            resource in f.get("metric", "").lower() 
            for resource in ["cpu", "memory", "disk", "network"]
        )]
        
        if resource_anomalies:
            recommendations.append("Investigate system resource utilization patterns")
            recommendations.append("Consider scaling resources if sustained high usage")
        
        # General recommendations
        if len(findings) > 3:
            recommendations.append("Multiple anomalies detected - perform comprehensive system review")
        
        return recommendations
    
    async def _update_anomaly_tracking(self, findings: List[Dict[str, Any]]):
        """Update anomaly tracking data"""
        try:
            # Add to recent anomalies
            for finding in findings:
                self.recent_anomalies.append({
                    "timestamp": datetime.utcnow(),
                    "finding": finding
                })
            
            # Keep only recent anomalies (last 24 hours)
            cutoff_time = datetime.utcnow() - timedelta(hours=24)
            self.recent_anomalies = [
                a for a in self.recent_anomalies 
                if a["timestamp"] > cutoff_time
            ]
        
        except Exception as e:
            self.logger.error(f"Error updating anomaly tracking: {e}")


class PerformanceAnalyzer(BaseAnalyzer):
    """
    Advanced performance analysis system for identifying bottlenecks,
    optimization opportunities, and performance trends.
    """
    
    def __init__(self, config: MonitoringConfig):
        super().__init__("performance_analyzer", config)
        
        # Performance thresholds
        self.performance_thresholds = {
            "cpu_warning": 70.0,
            "cpu_critical": 90.0,
            "memory_warning": 75.0,
            "memory_critical": 90.0,
            "disk_warning": 80.0,
            "disk_critical": 95.0,
            "response_time_warning": 1.0,
            "response_time_critical": 5.0
        }
        
        # Performance baseline
        self.performance_baseline: Dict[str, float] = {}
        self.performance_history: List[Dict[str, Any]] = []
        
    async def analyze(self, metrics_data: Dict[str, Any]) -> AnalysisResult:
        """Analyze performance metrics"""
        findings = []
        
        try:
            # Extract performance metrics
            performance_metrics = await self._extract_performance_metrics(metrics_data)
            
            # Analyze resource utilization
            resource_findings = await self._analyze_resource_utilization(performance_metrics)
            findings.extend(resource_findings)
            
            # Analyze response times
            response_findings = await self._analyze_response_times(performance_metrics)
            findings.extend(response_findings)
            
            # Calculate performance score
            performance_score = self._calculate_performance_score(performance_metrics)
            
            # Determine severity
            severity = self._determine_performance_severity(findings, performance_score)
            
            # Generate recommendations
            recommendations = await self._generate_performance_recommendations(findings, performance_metrics)
            
            return AnalysisResult(
                analysis_type=AnalysisType.PERFORMANCE_ANALYSIS,
                timestamp=datetime.utcnow(),
                metrics_analyzed=list(performance_metrics.keys()),
                findings=findings,
                confidence_score=0.8,
                severity=severity,
                recommendations=recommendations,
                metadata={
                    "performance_score": performance_score,
                    "baseline_available": bool(self.performance_baseline),
                    "history_size": len(self.performance_history)
                }
            )
            
        except Exception as e:
            self.logger.error(f"Error in performance analysis: {e}")
            raise
    
    async def _extract_performance_metrics(self, metrics_data: Dict[str, Any]) -> Dict[str, Any]:
        """Extract performance-relevant metrics"""
        performance_metrics = {}
        
        for source, data in metrics_data.items():
            if isinstance(data, dict) and "metrics" in data:
                metrics = data["metrics"]
                
                # Extract system metrics
                if "cpu" in metrics:
                    performance_metrics["cpu_usage"] = metrics["cpu"].get("usage_percent", 0)
                
                if "memory" in metrics:
                    performance_metrics["memory_usage"] = metrics["memory"]["virtual"].get("percent", 0)
        
        return performance_metrics
    
    async def _analyze_resource_utilization(self, metrics: Dict[str, Any]) -> List[Dict[str, Any]]:
        """Analyze resource utilization patterns"""
        findings = []
        
        for resource in ["cpu_usage", "memory_usage"]:
            if resource not in metrics:
                continue
            
            value = metrics[resource]
            resource_name = resource.replace("_usage", "")
            
            # Check against thresholds
            warning_threshold = self.performance_thresholds.get(f"{resource_name}_warning", 80)
            critical_threshold = self.performance_thresholds.get(f"{resource_name}_critical", 95)
            
            if value >= critical_threshold:
                findings.append({
                    "type": "resource_utilization",
                    "severity": "critical",
                    "resource": resource_name,
                    "value": value,
                    "threshold": critical_threshold,
                    "description": f"Critical {resource_name} utilization: {value:.1f}%"
                })
            elif value >= warning_threshold:
                findings.append({
                    "type": "resource_utilization",
                    "severity": "warning", 
                    "resource": resource_name,
                    "value": value,
                    "threshold": warning_threshold,
                    "description": f"High {resource_name} utilization: {value:.1f}%"
                })
        
        return findings
    
    async def _analyze_response_times(self, metrics: Dict[str, Any]) -> List[Dict[str, Any]]:
        """Analyze response time performance"""
        findings = []
        
        if "avg_response_time" in metrics:
            avg_response_time = metrics["avg_response_time"]
            
            if avg_response_time >= self.performance_thresholds["response_time_critical"]:
                findings.append({
                    "type": "response_time",
                    "severity": "critical",
                    "value": avg_response_time,
                    "threshold": self.performance_thresholds["response_time_critical"],
                    "description": f"Critical response time: {avg_response_time:.2f}s"
                })
            elif avg_response_time >= self.performance_thresholds["response_time_warning"]:
                findings.append({
                    "type": "response_time",
                    "severity": "warning",
                    "value": avg_response_time,
                    "threshold": self.performance_thresholds["response_time_warning"],
                    "description": f"Slow response time: {avg_response_time:.2f}s"
                })
        
        return findings
    
    def _calculate_performance_score(self, metrics: Dict[str, Any]) -> float:
        """Calculate overall performance score (0-100)"""
        score = 100.0
        
        # CPU impact
        if "cpu_usage" in metrics:
            cpu_usage = metrics["cpu_usage"]
            if cpu_usage > 80:
                score -= (cpu_usage - 80) * 2
        
        # Memory impact
        if "memory_usage" in metrics:
            memory_usage = metrics["memory_usage"]
            if memory_usage > 75:
                score -= (memory_usage - 75) * 1.5
        
        return max(0.0, min(100.0, score))
    
    def _determine_performance_severity(self, findings: List[Dict[str, Any]], performance_score: float) -> str:
        """Determine overall performance severity"""
        critical_findings = [f for f in findings if f.get("severity") == "critical"]
        warning_findings = [f for f in findings if f.get("severity") == "warning"]
        
        if critical_findings or performance_score < 40:
            return "critical"
        elif warning_findings or performance_score < 70:
            return "warning"
        else:
            return "info"
    
    async def _generate_performance_recommendations(self, findings: List[Dict[str, Any]], metrics: Dict[str, Any]) -> List[str]:
        """Generate performance optimization recommendations"""
        recommendations = []
        
        # Resource-specific recommendations
        for finding in findings:
            if finding.get("type") == "resource_utilization":
                resource = finding.get("resource")
                
                if resource == "cpu":
                    recommendations.extend([
                        "Consider CPU optimization: profiling, caching, algorithm improvements",
                        "Evaluate horizontal scaling or CPU upgrade"
                    ])
                elif resource == "memory":
                    recommendations.extend([
                        "Investigate memory leaks and optimize memory usage",
                        "Consider increasing available memory"
                    ])
        
        return list(set(recommendations))


class TrendAnalyzer(BaseAnalyzer):
    """
    Advanced trend analysis system for identifying patterns and trends
    """
    
    def __init__(self, config: MonitoringConfig):
        super().__init__("trend_analyzer", config)
        
        # Time series data storage
        self.time_series_data: Dict[str, List[Tuple[datetime, float]]] = {}
        
    async def analyze(self, metrics_data: Dict[str, Any]) -> AnalysisResult:
        """Analyze trends in metrics data"""
        findings = []
        
        try:
            # Extract time series metrics
            current_timestamp = datetime.utcnow()
            time_series_metrics = await self._extract_time_series_metrics(metrics_data, current_timestamp)
            
            # Update historical data
            await self._update_time_series_data(time_series_metrics, current_timestamp)
            
            # Analyze trends for each metric
            for metric_name, data_points in self.time_series_data.items():
                if len(data_points) < 10:
                    continue
                
                # Linear trend analysis
                trend_findings = await self._analyze_linear_trends(metric_name, data_points)
                findings.extend(trend_findings)
            
            # Generate recommendations
            recommendations = await self._generate_trend_recommendations(findings)
            
            return AnalysisResult(
                analysis_type=AnalysisType.TREND_ANALYSIS,
                timestamp=datetime.utcnow(),
                metrics_analyzed=list(self.time_series_data.keys()),
                findings=findings,
                confidence_score=0.7,
                severity=self._determine_trend_severity(findings),
                recommendations=recommendations,
                metadata={
                    "time_series_count": len(self.time_series_data)
                }
            )
            
        except Exception as e:
            self.logger.error(f"Error in trend analysis: {e}")
            raise
    
    async def _extract_time_series_metrics(self, metrics_data: Dict[str, Any], timestamp: datetime) -> Dict[str, float]:
        """Extract metrics suitable for time series analysis"""
        time_series_metrics = {}
        
        for source, data in metrics_data.items():
            if isinstance(data, dict) and "metrics" in data:
                metrics = data["metrics"]
                
                # Extract numerical metrics recursively
                flattened = self._flatten_metrics(metrics, source)
                for metric_name, value in flattened.items():
                    if isinstance(value, (int, float)) and not math.isnan(value):
                        time_series_metrics[metric_name] = value
        
        return time_series_metrics
    
    def _flatten_metrics(self, metrics: Dict[str, Any], prefix: str = "") -> Dict[str, Any]:
        """Flatten nested metrics dictionary"""
        flattened = {}
        
        for key, value in metrics.items():
            new_key = f"{prefix}_{key}" if prefix else key
            
            if isinstance(value, dict):
                flattened.update(self._flatten_metrics(value, new_key))
            elif isinstance(value, (int, float)):
                flattened[new_key] = value
        
        return flattened
    
    async def _update_time_series_data(self, metrics: Dict[str, float], timestamp: datetime):
        """Update time series data with new metrics"""
        for metric_name, value in metrics.items():
            if metric_name not in self.time_series_data:
                self.time_series_data[metric_name] = []
            
            self.time_series_data[metric_name].append((timestamp, value))
            
            # Keep only recent data (e.g., last 7 days)
            cutoff_time = timestamp - timedelta(days=7)
            self.time_series_data[metric_name] = [
                (t, v) for t, v in self.time_series_data[metric_name]
                if t > cutoff_time
            ]
    
    async def _analyze_linear_trends(self, metric_name: str, data_points: List[Tuple[datetime, float]]) -> List[Dict[str, Any]]:
        """Analyze linear trends in time series data"""
        findings = []
        
        try:
            if len(data_points) < 10:
                return findings
            
            # Convert to numpy arrays for analysis
            timestamps = [t.timestamp() for t, v in data_points]
            values = [v for t, v in data_points]
            
            # Calculate linear regression
            x = np.array(timestamps)
            y = np.array(values)
            
            # Normalize timestamps to start from 0
            x = x - x[0]
            
            slope, intercept, r_value, p_value, std_err = stats.linregress(x, y)
            
            # Determine trend significance
            if abs(r_value) > 0.5 and p_value < 0.05:
                trend_type = "increasing" if slope > 0 else "decreasing"
                
                # Calculate trend strength
                trend_strength = abs(r_value)
                
                findings.append({
                    "type": "linear_trend",
                    "metric": metric_name,
                    "trend_type": trend_type,
                    "slope": slope,
                    "correlation": r_value,
                    "p_value": p_value,
                    "trend_strength": trend_strength,
                    "confidence": trend_strength,
                    "description": f"{trend_type.capitalize()} trend detected in {metric_name} (r={r_value:.3f})"
                })
        
        except Exception as e:
            self.logger.error(f"Error in linear trend analysis for {metric_name}: {e}")
        
        return findings
    
    def _determine_trend_severity(self, findings: List[Dict[str, Any]]) -> str:
        """Determine severity based on trend findings"""
        critical_patterns = [
            f for f in findings 
            if (f.get("trend_type") == "decreasing" and f.get("confidence", 0) > 0.8)
        ]
        
        if critical_patterns:
            return "warning"
        elif findings:
            return "info"
        else:
            return "info"
    
    async def _generate_trend_recommendations(self, findings: List[Dict[str, Any]]) -> List[str]:
        """Generate trend-based recommendations"""
        recommendations = []
        
        for finding in findings:
            if finding.get("trend_type") == "increasing" and finding.get("confidence", 0) > 0.7:
                metric = finding.get("metric", "")
                if "cpu" in metric.lower() or "memory" in metric.lower():
                    recommendations.append(f"Monitor {metric} - increasing trend detected")
        
        return recommendations


# Factory function for creating analyzers
def create_analyzers(config: MonitoringConfig) -> Dict[str, BaseAnalyzer]:
    """Create and return all standard analyzers"""
    analyzers = {
        "anomaly_detector": AnomalyDetector(config),
        "performance_analyzer": PerformanceAnalyzer(config),
        "trend_analyzer": TrendAnalyzer(config)
    }
    
    return analyzers


