@dataclass
class UploadProcessingConfiguration:
    """Main upload processing configuration."""
    
    # Core settings
    enabled: bool = True
    debug_mode: bool = field(default_factory=lambda: os.getenv("DEBUG", "false").lower() == "true")
    
    # Processing components
    format_configs: Dict[ContentFormat, FormatProcessingConfig] = field(default_factory=dict)
    upload_limits: UploadLimits = field(default_factory=UploadLimits)
    processing_queue: ProcessingQueue = field(default_factory=ProcessingQueue)
    content_validation: ContentValidation = field(default_factory=ContentValidation)
    metadata_extraction: MetadataExtraction = field(default_factory=MetadataExtraction)
    
    # Storage configuration
    temporary_storage_path: str = "/tmp/uploads"
    permanent_storage_path: str = "/data/uploads"
    backup_storage_enabled: bool = True
    cloud_storage_enabled: bool = True
    
    # Processing pipeline
    enable_parallel_processing: bool = True
    enable_distributed_processing: bool = False
    processing_threads: int = 4
    
    # Monitoring and logging
    enable_progress_tracking: bool = True
    enable_detailed_logging: bool = True
    enable_performance_metrics: bool = True
    
    # Security settings
    enable_encryption_at_rest: bool = True
    enable_encryption_in_transit: bool = True
    require_authentication: bool = True
    enable_audit_logging: bool = True
    
    @classmethod
    def create_default_format_configs(cls) -> Dict[ContentFormat, FormatProcessingConfig]:
        """Create default format-specific configurations."""
        configs = {}
        
        # Audio formats
        audio_config = FormatProcessingConfig(
            max_file_size_mb=500,
            allowed_extensions={".mp3", ".wav", ".flac", ".aac", ".ogg"},
            audio_normalization=True,
            noise_reduction=True,
            auto_tagging=True,
            spectrum_analysis=True
        )
        
        for fmt in [ContentFormat.AUDIO_MP3, ContentFormat.AUDIO_WAV, 
                   ContentFormat.AUDIO_FLAC, ContentFormat.AUDIO_AAC, ContentFormat.AUDIO_OGG]:
            configs[fmt] = audio_config
        
        # Video formats
        video_config = FormatProcessingConfig(
            max_file_size_mb=2000,
            allowed_extensions={".mp4", ".avi", ".mov", ".wmv", ".flv", ".webm"},
            video_transcoding=True,
            keyframe_extraction=True,
            motion_analysis=True,
            face_detection=True
        )
        
        for fmt in [ContentFormat.VIDEO_MP4, ContentFormat.VIDEO_AVI, 
                   ContentFormat.VIDEO_MOV, ContentFormat.VIDEO_WMV, 
                   ContentFormat.VIDEO_FLV, ContentFormat.VIDEO_WEBM]:
            configs[fmt] = video_config
        
        # Image formats
        image_config = FormatProcessingConfig(
            max_file_size_mb=100,
            allowed_extensions={".jpg", ".jpeg", ".png", ".gif", ".webp", ".svg", ".tiff"},
            auto_enhancement=True,
            object_detection=True,
            text_extraction=True,
            color_analysis=True
        )
        
        for fmt in [ContentFormat.IMAGE_JPEG, ContentFormat.IMAGE_PNG, 
                   ContentFormat.IMAGE_GIF, ContentFormat.IMAGE_WEBP,
                   ContentFormat.IMAGE_SVG, ContentFormat.IMAGE_TIFF]:
            configs[fmt] = image_config
        
        return configs
    
    def validate_configuration(self) -> List[str]:
        """Validate the upload processing configuration."""
        errors = []
        
        if not self.temporary_storage_path:
            errors.append("temporary_storage_path cannot be empty")
        
        if not self.permanent_storage_path:
            errors.append("permanent_storage_path cannot be empty")
        
        if self.processing_queue.max_concurrent_jobs <= 0:
            errors.append("max_concurrent_jobs must be positive")
        
        if self.upload_limits.max_single_file_size <= 0:
            errors.append("max_single_file_size must be positive")
        
        # Validate format configurations
        if not self.format_configs:
            self.format_configs = self.create_default_format_configs()
        
        return errors
    
    @classmethod
    def create_development_config(cls) -> 'UploadProcessingConfiguration':
        """Create configuration for development environment."""
        config = cls()
        config.debug_mode = True
        config.upload_limits.max_single_file_size = 100  # 100MB for dev
        config.processing_queue.max_concurrent_jobs = 2
        config.enable_distributed_processing = False
        config.cloud_storage_enabled = False
        return config
    
    @classmethod
    def create_production_config(cls) -> 'UploadProcessingConfiguration':
        """Create configuration for production environment."""
        config = cls()
        config.debug_mode = False
        config.upload_limits.max_single_file_size = 2000  # 2GB for prod
        config.processing_queue.max_concurrent_jobs = 10
        config.enable_distributed_processing = True
        config.cloud_storage_enabled = True
        config.backup_storage_enabled = True
        return config
    
    @classmethod
    def create_enterprise_config(cls) -> 'UploadProcessingConfiguration':
        """Create configuration for enterprise environment."""
        config = cls.create_production_config()
        config.upload_limits.max_single_file_size = 10000  # 10GB for enterprise
        config.processing_queue.max_concurrent_jobs = 20
        config.processing_threads = 8
        config.enable_encryption_at_rest = True
        config.enable_encryption_in_transit = True
        config.enable_audit_logging = True
        return config


# Export default configuration
def get_upload_processing_config() -> UploadProcessingConfiguration:
    """Get upload processing configuration based on environment."""
    env = os.getenv("ENVIRONMENT", "development").lower()
    
    if env == "production":
        return UploadProcessingConfiguration.create_production_config()
    elif env == "enterprise":
        return UploadProcessingConfiguration.create_enterprise_config()
    else:
        return UploadProcessingConfiguration.create_development_config()


