import asyncio
import hashlib
import logging
import numpy as np
import cv2 as cv
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional, Any, Union, Tuple
from dataclasses import dataclass
from enum import Enum

from ..ai_protection_config import AIProtectionConfiguration
from .content_protection_service import ContentFormat


class FingerprintType(Enum):
    """Types of fingerprints."""
    AUDIO_SPECTRAL = "audio_spectral"
    AUDIO_CHROMAPRINT = "audio_chromaprint"
    VIDEO_FRAME = "video_frame"
    VIDEO_MOTION = "video_motion"
    IMAGE_PERCEPTUAL = "image_perceptual"
    IMAGE_FEATURE = "image_feature"
    TEXT_SEMANTIC = "text_semantic"
    TEXT_NGRAM = "text_ngram"
    COMBINED = "combined"


@dataclass
class FingerprintResult:
    """Fingerprint generation result."""
    success: bool
    fingerprint_hash: str
    fingerprint_type: FingerprintType
    fingerprint_data: Dict[str, Any]
    similarity_threshold: float
    processing_time: float
    metadata: Dict[str, Any]
    error: Optional[str] = None


class FingerprintingService:
    """
    Enterprise-grade content fingerprinting service.
    
    Provides multi-format content fingerprinting using advanced algorithms
    for audio, video, image, and text content.
    """
    
    def __init__(self, config: AIProtectionConfiguration):
        """Initialize the fingerprinting service."""
        self.config = config
        self.logger = logging.getLogger(__name__)
        self._initialize_engines()
    
    def _initialize_engines(self):
        """Initialize fingerprinting engines."""
        from ..engines.audio_fingerprint_engine import AudioFingerprintEngine
        from ..engines.video_fingerprint_engine import VideoFingerprintEngine
        from ..engines.image_fingerprint_engine import ImageFingerprintEngine
        from ..engines.text_fingerprint_engine import TextFingerprintEngine
        
        if self.config.fingerprinting.enable_audio_fingerprinting:
            self.audio_engine = AudioFingerprintEngine(self.config)
        
        if self.config.fingerprinting.enable_video_fingerprinting:
            self.video_engine = VideoFingerprintEngine(self.config)
        
        if self.config.fingerprinting.enable_image_fingerprinting:
            self.image_engine = ImageFingerprintEngine(self.config)
        
        if self.config.fingerprinting.enable_text_fingerprinting:
            self.text_engine = TextFingerprintEngine(self.config)
    
    async def generate_fingerprint(
        self,
        content_path: Union[str, Path],
        content_format: ContentFormat,
        fingerprint_types: Optional[List[FingerprintType]] = None
    ) -> FingerprintResult:
        """
        Generate comprehensive fingerprint for content.
        
        Args:
            content_path: Path to content file
            content_format: Format of the content
            fingerprint_types: Specific fingerprint types to generate
            
        Returns:
            FingerprintResult with fingerprint data
        """
        start_time = datetime.now()
        
        try:
            self.logger.info(f"Generating fingerprint for {content_path}")
            
            # Determine fingerprint types based on content format
            if fingerprint_types is None:
                fingerprint_types = self._get_default_fingerprint_types(content_format)
            
            # Generate fingerprints based on content type
            fingerprint_data = {}
            
            if content_format == ContentFormat.AUDIO:
                fingerprint_data = await self._generate_audio_fingerprint(content_path)
            elif content_format == ContentFormat.VIDEO:
                fingerprint_data = await self._generate_video_fingerprint(content_path)
            elif content_format == ContentFormat.IMAGE:
                fingerprint_data = await self._generate_image_fingerprint(content_path)
            elif content_format == ContentFormat.TEXT:
                fingerprint_data = await self._generate_text_fingerprint(content_path)
            else:
                fingerprint_data = await self._generate_mixed_media_fingerprint(content_path)
            
            # Create combined hash
            combined_hash = self._create_combined_hash(fingerprint_data)
            
            processing_time = (datetime.now() - start_time).total_seconds()
            
            self.logger.info(f"Fingerprint generated in {processing_time:.2f}s")
            
            return FingerprintResult(
                success=True,
                fingerprint_hash=combined_hash,
                fingerprint_type=FingerprintType.COMBINED,
                fingerprint_data=fingerprint_data,
                similarity_threshold=self._get_similarity_threshold(content_format),
                processing_time=processing_time,
                metadata={
                    "content_format": content_format.value,
                    "fingerprint_types": [ft.value for ft in fingerprint_types],
                    "generated_at": datetime.now().isoformat()
                }
            )
            
        except Exception as e:
            processing_time = (datetime.now() - start_time).total_seconds()
            self.logger.error(f"Fingerprint generation failed: {e}")
            
            return FingerprintResult(
                success=False,
                fingerprint_hash="",
                fingerprint_type=FingerprintType.COMBINED,
                fingerprint_data={},
                similarity_threshold=0.0,
                processing_time=processing_time,
                metadata={},
                error=str(e)
            )
    
    async def compare_fingerprints(
        self,
        fingerprint1: str,
        fingerprint2: str,
        fingerprint_data1: Dict[str, Any],
        fingerprint_data2: Dict[str, Any]
    ) -> float:
        """
        Compare two fingerprints and return similarity score.
        
        Args:
            fingerprint1: First fingerprint hash
            fingerprint2: Second fingerprint hash
            fingerprint_data1: First fingerprint data
            fingerprint_data2: Second fingerprint data
            
        Returns:
            Similarity score between 0 and 1
        """
        try:
            # Quick hash comparison
            if fingerprint1 == fingerprint2:
                return 1.0
            
            # Detailed comparison based on fingerprint data
            similarity_scores = []
            
            # Compare audio fingerprints
            if "audio" in fingerprint_data1 and "audio" in fingerprint_data2:
                audio_similarity = await self._compare_audio_fingerprints(
                    fingerprint_data1["audio"], fingerprint_data2["audio"]
                )
                similarity_scores.append(audio_similarity)
            
            # Compare video fingerprints
            if "video" in fingerprint_data1 and "video" in fingerprint_data2:
                video_similarity = await self._compare_video_fingerprints(
                    fingerprint_data1["video"], fingerprint_data2["video"]
                )
                similarity_scores.append(video_similarity)
            
            # Compare image fingerprints
            if "image" in fingerprint_data1 and "image" in fingerprint_data2:
                image_similarity = await self._compare_image_fingerprints(
                    fingerprint_data1["image"], fingerprint_data2["image"]
                )
                similarity_scores.append(image_similarity)
            
            # Compare text fingerprints
            if "text" in fingerprint_data1 and "text" in fingerprint_data2:
                text_similarity = await self._compare_text_fingerprints(
                    fingerprint_data1["text"], fingerprint_data2["text"]
                )
                similarity_scores.append(text_similarity)
            
            # Return average similarity if multiple types, otherwise 0
            return sum(similarity_scores) / len(similarity_scores) if similarity_scores else 0.0
            
        except Exception as e:
            self.logger.error(f"Fingerprint comparison failed: {e}")
            return 0.0
    
    def _get_default_fingerprint_types(self, content_format: ContentFormat) -> List[FingerprintType]:
        """Get default fingerprint types for content format."""
        type_mapping = {
            ContentFormat.AUDIO: [FingerprintType.AUDIO_SPECTRAL, FingerprintType.AUDIO_CHROMAPRINT],
            ContentFormat.VIDEO: [FingerprintType.VIDEO_FRAME, FingerprintType.VIDEO_MOTION, FingerprintType.AUDIO_SPECTRAL],
            ContentFormat.IMAGE: [FingerprintType.IMAGE_PERCEPTUAL, FingerprintType.IMAGE_FEATURE],
            ContentFormat.TEXT: [FingerprintType.TEXT_SEMANTIC, FingerprintType.TEXT_NGRAM],
            ContentFormat.DOCUMENT: [FingerprintType.TEXT_SEMANTIC, FingerprintType.TEXT_NGRAM],
            ContentFormat.MIXED_MEDIA: [FingerprintType.COMBINED]
        }
        
        return type_mapping.get(content_format, [FingerprintType.COMBINED])
    
    async def _generate_audio_fingerprint(self, content_path: Union[str, Path]) -> Dict[str, Any]:
        """Generate audio fingerprint."""
        fingerprint_data = {}
        
        if hasattr(self, 'audio_engine'):
            # Spectral fingerprint
            if self.config.fingerprinting.enable_audio_fingerprinting:
                spectral_fp = await self.audio_engine.generate_spectral_fingerprint(content_path)
                fingerprint_data["spectral"] = spectral_fp
            
            # Chromaprint fingerprint
            chromaprint_fp = await self.audio_engine.generate_chromaprint(content_path)
            fingerprint_data["chromaprint"] = chromaprint_fp
            
            # MFCC features
            mfcc_features = await self.audio_engine.extract_mfcc_features(content_path)
            fingerprint_data["mfcc"] = mfcc_features
            
            # Tempo and beat tracking
            rhythm_features = await self.audio_engine.extract_rhythm_features(content_path)
            fingerprint_data["rhythm"] = rhythm_features
        
        return {"audio": fingerprint_data}
    
    async def _generate_video_fingerprint(self, content_path: Union[str, Path]) -> Dict[str, Any]:
        """Generate video fingerprint."""
        fingerprint_data = {}
        
        if hasattr(self, 'video_engine'):
            # Frame-based fingerprint
            frame_fp = await self.video_engine.generate_frame_fingerprint(content_path)
            fingerprint_data["frames"] = frame_fp
            
            # Motion vector analysis
            if self.config.fingerprinting.enable_motion_vectors:
                motion_fp = await self.video_engine.analyze_motion_vectors(content_path)
                fingerprint_data["motion"] = motion_fp
            
            # Color histogram analysis
            if self.config.fingerprinting.enable_color_histograms:
                color_fp = await self.video_engine.analyze_color_histograms(content_path)
                fingerprint_data["color"] = color_fp
            
            # Audio track fingerprint (if present)
            audio_track_fp = await self.video_engine.extract_audio_fingerprint(content_path)
            fingerprint_data["audio_track"] = audio_track_fp
        
        return {"video": fingerprint_data}
    
    async def _generate_image_fingerprint(self, content_path: Union[str, Path]) -> Dict[str, Any]:
        """Generate image fingerprint."""
        fingerprint_data = {}
        
        if hasattr(self, 'image_engine'):
            # Perceptual hash
            phash = await self.image_engine.generate_perceptual_hash(content_path)
            fingerprint_data["phash"] = phash
            
            # Feature matching
            if self.config.fingerprinting.enable_feature_matching:
                features = await self.image_engine.extract_features(content_path)
                fingerprint_data["features"] = features
            
            # Color analysis
            color_analysis = await self.image_engine.analyze_colors(content_path)
            fingerprint_data["colors"] = color_analysis
            
            # Texture analysis
            texture_analysis = await self.image_engine.analyze_texture(content_path)
            fingerprint_data["texture"] = texture_analysis
        
        return {"image": fingerprint_data}
    
    async def _generate_text_fingerprint(self, content_path: Union[str, Path]) -> Dict[str, Any]:
        """Generate text fingerprint."""
        fingerprint_data = {}
        
        if hasattr(self, 'text_engine'):
            # Read text content
            with open(content_path, 'r', encoding='utf-8') as f:
                text_content = f.read()
            
            # N-gram analysis
            ngram_fp = await self.text_engine.generate_ngram_fingerprint(text_content)
            fingerprint_data["ngrams"] = ngram_fp
            
            # Semantic analysis
            if self.config.fingerprinting.enable_semantic_analysis:
                semantic_fp = await self.text_engine.generate_semantic_fingerprint(text_content)
                fingerprint_data["semantic"] = semantic_fp
            
            # Style analysis
            style_fp = await self.text_engine.analyze_writing_style(text_content)
            fingerprint_data["style"] = style_fp
            
            # Content structure
            structure_fp = await self.text_engine.analyze_structure(text_content)
            fingerprint_data["structure"] = structure_fp
        
        return {"text": fingerprint_data}
    
    async def _generate_mixed_media_fingerprint(self, content_path: Union[str, Path]) -> Dict[str, Any]:
        """Generate fingerprint for mixed media content."""
        # Analyze file to determine what types of content it contains
        # For now, return a basic hash-based fingerprint
        with open(content_path, 'rb') as f:
            content = f.read()
        
        file_hash = hashlib.sha256(content).hexdigest()
        
        return {
            "mixed_media": {
                "file_hash": file_hash,
                "file_size": len(content),
                "type": "mixed_media"
            }
        }
    
    def _create_combined_hash(self, fingerprint_data: Dict[str, Any]) -> str:
        """Create combined hash from all fingerprint data."""
        # Serialize fingerprint data and create hash
        import json
        
        # Sort keys for consistent hashing
        data_str = json.dumps(fingerprint_data, sort_keys=True)
        return hashlib.sha256(data_str.encode()).hexdigest()
    
    def _get_similarity_threshold(self, content_format: ContentFormat) -> float:
        """Get similarity threshold for content format."""
        # Return appropriate thresholds based on content type
        thresholds = {
            ContentFormat.AUDIO: self.config.copyright_detection.similarity_threshold,
            ContentFormat.VIDEO: self.config.copyright_detection.similarity_threshold,
            ContentFormat.IMAGE: self.config.fingerprinting.image_hash_size / 64.0,
            ContentFormat.TEXT: self.config.fingerprinting.text_min_similarity,
            ContentFormat.DOCUMENT: self.config.fingerprinting.text_min_similarity,
            ContentFormat.MIXED_MEDIA: 0.85
        }
        
        return thresholds.get(content_format, 0.80)
    
    async def _compare_audio_fingerprints(self, fp1: Dict[str, Any], fp2: Dict[str, Any]) -> float:
        """Compare audio fingerprints."""
        similarities = []
        
        # Compare spectral fingerprints
        if "spectral" in fp1 and "spectral" in fp2:
            spectral_sim = self._compare_spectral_features(fp1["spectral"], fp2["spectral"])
            similarities.append(spectral_sim)
        
        # Compare chromaprints
        if "chromaprint" in fp1 and "chromaprint" in fp2:
            chromaprint_sim = self._compare_chromaprints(fp1["chromaprint"], fp2["chromaprint"])
            similarities.append(chromaprint_sim)
        
        # Compare MFCC features
        if "mfcc" in fp1 and "mfcc" in fp2:
            mfcc_sim = self._compare_mfcc_features(fp1["mfcc"], fp2["mfcc"])
            similarities.append(mfcc_sim)
        
        return sum(similarities) / len(similarities) if similarities else 0.0
    
    async def _compare_video_fingerprints(self, fp1: Dict[str, Any], fp2: Dict[str, Any]) -> float:
        """Compare video fingerprints."""
        similarities = []
        
        # Compare frame fingerprints
        if "frames" in fp1 and "frames" in fp2:
            frame_sim = self._compare_frame_fingerprints(fp1["frames"], fp2["frames"])
            similarities.append(frame_sim)
        
        # Compare motion vectors
        if "motion" in fp1 and "motion" in fp2:
            motion_sim = self._compare_motion_vectors(fp1["motion"], fp2["motion"])
            similarities.append(motion_sim)
        
        return sum(similarities) / len(similarities) if similarities else 0.0
    
    async def _compare_image_fingerprints(self, fp1: Dict[str, Any], fp2: Dict[str, Any]) -> float:
        """Compare image fingerprints."""
        similarities = []
        
        # Compare perceptual hashes
        if "phash" in fp1 and "phash" in fp2:
            phash_sim = self._compare_perceptual_hashes(fp1["phash"], fp2["phash"])
            similarities.append(phash_sim)
        
        # Compare features
        if "features" in fp1 and "features" in fp2:
            feature_sim = self._compare_image_features(fp1["features"], fp2["features"])
            similarities.append(feature_sim)
        
        return sum(similarities) / len(similarities) if similarities else 0.0
    
    async def _compare_text_fingerprints(self, fp1: Dict[str, Any], fp2: Dict[str, Any]) -> float:
        """Compare text fingerprints."""
        similarities = []
        
        # Compare n-grams
        if "ngrams" in fp1 and "ngrams" in fp2:
            ngram_sim = self._compare_ngrams(fp1["ngrams"], fp2["ngrams"])
            similarities.append(ngram_sim)
        
        # Compare semantic embeddings
        if "semantic" in fp1 and "semantic" in fp2:
            semantic_sim = self._compare_semantic_embeddings(fp1["semantic"], fp2["semantic"])
            similarities.append(semantic_sim)
        
        return sum(similarities) / len(similarities) if similarities else 0.0
    
