    def _compare_perceptual_hashes(self, fp1: str, fp2: str) -> float:
        """Compare perceptual hashes."""
        # Calculate Hamming distance
        if len(fp1) != len(fp2):
            return 0.0
        
        hamming_distance = sum(c1 != c2 for c1, c2 in zip(fp1, fp2))
        similarity = 1.0 - (hamming_distance / len(fp1))
        return similarity
    
