"""
Custom Exceptions for AI Fingerprinting System

Defines specialized exception classes for comprehensive error handling
throughout the fingerprinting pipeline with detailed error information.
"""

from typing import Optional, Dict, Any
from datetime import datetime


class FingerprintingError(Exception):
    """Base exception class for all fingerprinting operations"""
    
    def __init__(
        self,
        message: str,
        error_code: Optional[str] = None,
        details: Optional[Dict[str, Any]] = None,
        original_exception: Optional[Exception] = None
    ):
        self.message = message
        self.error_code = error_code or "FINGERPRINT_ERROR"
        self.details = details or {}
        self.original_exception = original_exception
        self.timestamp = datetime.utcnow()
        
        super().__init__(self.message)
    
    def to_dict(self) -> Dict[str, Any]:
        """Convert exception to dictionary for logging/API responses"""
        return {
            "error_type": self.__class__.__name__,
            "error_code": self.error_code,
            "message": self.message,
            "details": self.details,
            "timestamp": self.timestamp.isoformat(),
            "original_exception": str(self.original_exception) if self.original_exception else None
        }


class UnsupportedFormatError(FingerprintingError):
    """Raised when content format is not supported for fingerprinting"""
    
    def __init__(
        self,
        content_format: str,
        supported_formats: Optional[list] = None,
        **kwargs
    ):
        self.content_format = content_format
        self.supported_formats = supported_formats or []
        
        message = f"Unsupported content format: {content_format}"
        if self.supported_formats:
            message += f". Supported formats: {', '.join(self.supported_formats)}"
        
        super().__init__(
            message=message,
            error_code="UNSUPPORTED_FORMAT",
            details={
                "content_format": content_format,
                "supported_formats": self.supported_formats
            },
            **kwargs
        )


class ProcessingError(FingerprintingError):
    """Raised when content processing fails during fingerprinting"""
    
    def __init__(
        self,
        processing_stage: str,
        content_id: Optional[str] = None,
        processing_time: Optional[float] = None,
        **kwargs
    ):
        self.processing_stage = processing_stage
        self.content_id = content_id
        self.processing_time = processing_time
        
        message = f"Processing failed at stage: {processing_stage}"
        if content_id:
            message += f" for content: {content_id}"
        
        super().__init__(
            message=message,
            error_code="PROCESSING_ERROR",
            details={
                "processing_stage": processing_stage,
                "content_id": content_id,
                "processing_time": processing_time
            },
            **kwargs
        )


class ExtractionError(FingerprintingError):
    """Raised when fingerprint feature extraction fails"""
    
    def __init__(
        self,
        extraction_method: str,
        feature_type: Optional[str] = None,
        content_quality: Optional[str] = None,
        **kwargs
    ):
        self.extraction_method = extraction_method
        self.feature_type = feature_type
        self.content_quality = content_quality
        
        message = f"Feature extraction failed using method: {extraction_method}"
        if feature_type:
            message += f" for feature type: {feature_type}"
        
        super().__init__(
            message=message,
            error_code="EXTRACTION_ERROR",
            details={
                "extraction_method": extraction_method,
                "feature_type": feature_type,
                "content_quality": content_quality
            },
            **kwargs
        )


class ValidationError(FingerprintingError):
    """Raised when content validation fails before processing"""
    
    def __init__(
        self,
        validation_type: str,
        validation_rules: Optional[Dict[str, Any]] = None,
        actual_values: Optional[Dict[str, Any]] = None,
        **kwargs
    ):
        self.validation_type = validation_type
        self.validation_rules = validation_rules or {}
        self.actual_values = actual_values or {}
        
        message = f"Content validation failed: {validation_type}"
        
        super().__init__(
            message=message,
            error_code="VALIDATION_ERROR",
            details={
                "validation_type": validation_type,
                "validation_rules": validation_rules,
                "actual_values": actual_values
            },
            **kwargs
        )


class ModelLoadError(FingerprintingError):
    """Raised when AI models fail to load for fingerprinting"""
    
    def __init__(
        self,
        model_name: str,
        model_path: Optional[str] = None,
        model_version: Optional[str] = None,
        **kwargs
    ):
        self.model_name = model_name
        self.model_path = model_path
        self.model_version = model_version
        
        message = f"Failed to load AI model: {model_name}"
        if model_version:
            message += f" (version: {model_version})"
        
        super().__init__(
            message=message,
            error_code="MODEL_LOAD_ERROR",
            details={
                "model_name": model_name,
                "model_path": model_path,
                "model_version": model_version
            },
            **kwargs
        )


class StorageError(FingerprintingError):
    """Raised when fingerprint storage operations fail"""
    
    def __init__(
        self,
        operation: str,
        storage_backend: Optional[str] = None,
        fingerprint_id: Optional[str] = None,
        **kwargs
    ):
        self.operation = operation
        self.storage_backend = storage_backend
        self.fingerprint_id = fingerprint_id
        
        message = f"Storage operation failed: {operation}"
        if storage_backend:
            message += f" on backend: {storage_backend}"
        
        super().__init__(
            message=message,
            error_code="STORAGE_ERROR",
            details={
                "operation": operation,
                "storage_backend": storage_backend,
                "fingerprint_id": fingerprint_id
            },
            **kwargs
        )


class MatchingError(FingerprintingError):
    """Raised when fingerprint matching operations fail"""
    
    def __init__(
        self,
        matching_algorithm: str,
        query_fingerprint_id: Optional[str] = None,
        search_space_size: Optional[int] = None,
        **kwargs
    ):
        self.matching_algorithm = matching_algorithm
        self.query_fingerprint_id = query_fingerprint_id
        self.search_space_size = search_space_size
        
        message = f"Fingerprint matching failed using algorithm: {matching_algorithm}"
        
        super().__init__(
            message=message,
            error_code="MATCHING_ERROR",
            details={
                "matching_algorithm": matching_algorithm,
                "query_fingerprint_id": query_fingerprint_id,
                "search_space_size": search_space_size
            },
            **kwargs
        )


class ConfigurationError(FingerprintingError):
    """Raised when fingerprinting configuration is invalid"""
    
    def __init__(
        self,
        config_parameter: str,
        expected_type: Optional[str] = None,
        actual_value: Optional[Any] = None,
        **kwargs
    ):
        self.config_parameter = config_parameter
        self.expected_type = expected_type
        self.actual_value = actual_value
        
        message = f"Invalid configuration parameter: {config_parameter}"
        if expected_type:
            message += f" (expected type: {expected_type})"
        
        super().__init__(
            message=message,
            error_code="CONFIGURATION_ERROR",
            details={
                "config_parameter": config_parameter,
                "expected_type": expected_type,
                "actual_value": str(actual_value)
            },
            **kwargs
        )


class ResourceError(FingerprintingError):
    """Raised when system resources are insufficient for processing"""
    
    def __init__(
        self,
        resource_type: str,
        required_amount: Optional[str] = None,
        available_amount: Optional[str] = None,
        **kwargs
    ):
        self.resource_type = resource_type
        self.required_amount = required_amount
        self.available_amount = available_amount
        
        message = f"Insufficient system resources: {resource_type}"
        if required_amount and available_amount:
            message += f" (required: {required_amount}, available: {available_amount})"
        
        super().__init__(
            message=message,
            error_code="RESOURCE_ERROR",
            details={
                "resource_type": resource_type,
                "required_amount": required_amount,
                "available_amount": available_amount
            },
            **kwargs
        )


class TimeoutError(FingerprintingError):
    """Raised when processing operations exceed time limits"""
    
    def __init__(
        self,
        operation: str,
        timeout_seconds: int,
        actual_duration: Optional[float] = None,
        **kwargs
    ):
        self.operation = operation
        self.timeout_seconds = timeout_seconds
        self.actual_duration = actual_duration
        
        message = f"Operation timed out: {operation} (limit: {timeout_seconds}s)"
        if actual_duration:
            message += f" (actual: {actual_duration:.2f}s)"
        
        super().__init__(
            message=message,
            error_code="TIMEOUT_ERROR",
            details={
                "operation": operation,
                "timeout_seconds": timeout_seconds,
                "actual_duration": actual_duration
            },
            **kwargs
        )


# Exception hierarchy mapping for error handling
EXCEPTION_HIERARCHY = {
    "base": FingerprintingError,
    "format": UnsupportedFormatError,
    "processing": ProcessingError,
    "extraction": ExtractionError,
    "validation": ValidationError,
    "model": ModelLoadError,
    "storage": StorageError,
    "matching": MatchingError,
    "configuration": ConfigurationError,
    "resource": ResourceError,
    "timeout": TimeoutError,
}

# Error severity levels
ERROR_SEVERITY = {
    "CRITICAL": ["MODEL_LOAD_ERROR", "RESOURCE_ERROR", "CONFIGURATION_ERROR"],
    "HIGH": ["STORAGE_ERROR", "MATCHING_ERROR", "TIMEOUT_ERROR"],
    "MEDIUM": ["PROCESSING_ERROR", "EXTRACTION_ERROR", "VALIDATION_ERROR"],
    "LOW": ["UNSUPPORTED_FORMAT"]
}

# Recovery strategies by error type
RECOVERY_STRATEGIES = {
    "UNSUPPORTED_FORMAT": "format_conversion",
    "PROCESSING_ERROR": "retry_with_fallback",
    "EXTRACTION_ERROR": "alternative_algorithm",
    "MODEL_LOAD_ERROR": "fallback_model",
    "STORAGE_ERROR": "retry_with_backoff",
    "MATCHING_ERROR": "reduced_precision",
    "TIMEOUT_ERROR": "batch_processing",
    "RESOURCE_ERROR": "queue_for_later"
}
