"""
AI Audio Fingerprinting Engine
Protection et identification de contenu audio pour créateurs
"""
import librosa
import numpy as np
import chromaprint
from typing import Dict, List, Optional, Tuple
import hashlib
from sqlalchemy.orm import Session
from app.core.database import get_db
from app.models.orm.content_protection import AudioFingerprint
from app.services.ai.fingerprint_base import FingerprintBase


class AudioFingerprintEngine(FingerprintBase):
    """
    Moteur de fingerprinting audio avancé
    - Chromaprint pour la détection de similarité
    - Spectral hashing pour la robustesse
    - Extraction de features via Librosa
    """
    
    def __init__(self):
        self.sample_rate = 22050
        self.n_fft = 2048
        self.hop_length = 512
        self.n_mels = 128
        
    async def extract_fingerprint(self, audio_path: str) -> Dict:
        """
        Extrait le fingerprint audio multi-algorithmes
        
        Args:
            audio_path: Chemin vers le fichier audio
            
        Returns:
            Dict contenant tous les fingerprints
        """
        try:
            # Chargement audio avec Librosa
            y, sr = librosa.load(audio_path, sr=self.sample_rate)
            
            # 1. Chromaprint (standard industrie)
            chromaprint_fp = self._generate_chromaprint(audio_path)
            
            # 2. Spectral Centroid Features
            spectral_features = self._extract_spectral_features(y, sr)
            
            # 3. MFCC Features (robustes aux modifications)
            mfcc_features = self._extract_mfcc_features(y, sr)
            
            # 4. Tempo et Beat Features
            tempo_features = self._extract_tempo_features(y, sr)
            
            # 5. Hash perceptuel personnalisé
            perceptual_hash = self._generate_perceptual_hash(y, sr)
            
            fingerprint_data = {
                "chromaprint": chromaprint_fp,
                "spectral_features": spectral_features.tolist(),
                "mfcc_features": mfcc_features.tolist(),
                "tempo_features": tempo_features,
                "perceptual_hash": perceptual_hash,
                "duration": float(librosa.get_duration(y=y, sr=sr)),
                "sample_rate": sr
            }
            
            return fingerprint_data
            
        except Exception as e:
            raise Exception(f"Erreur extraction fingerprint audio: {str(e)}")
    
    def _generate_chromaprint(self, audio_path: str) -> str:
        """Génère le fingerprint Chromaprint"""
        try:
            # Utilisation de chromaprint (Acoustid)
            import subprocess
            result = subprocess.run([
                'fpcalc', '-raw', audio_path
            ], capture_output=True, text=True)
            
            if result.returncode == 0:
                return result.stdout.strip()
            else:
                # Fallback avec pyacoustid si disponible
                import acoustid
                duration, fp = acoustid.fingerprint_file(audio_path)
                return fp
                
        except Exception:
            return ""
    
    def _extract_spectral_features(self, y: np.ndarray, sr: int) -> np.ndarray:
        """Extrait les features spectrales"""
        # Spectral centroid
        spectral_centroids = librosa.feature.spectral_centroid(y=y, sr=sr)[0]
        
        # Spectral rolloff
        spectral_rolloff = librosa.feature.spectral_rolloff(y=y, sr=sr)[0]
        
        # Zero crossing rate
        zcr = librosa.feature.zero_crossing_rate(y)[0]
        
        # Spectral bandwidth
        spectral_bandwidth = librosa.feature.spectral_bandwidth(y=y, sr=sr)[0]
        
        # Concatenation des features
        features = np.concatenate([
            spectral_centroids,
            spectral_rolloff,
            zcr,
            spectral_bandwidth
        ])
        
        return features
    
    def _extract_mfcc_features(self, y: np.ndarray, sr: int) -> np.ndarray:
        """Extrait les MFCC (Mel-frequency cepstral coefficients)"""
        mfccs = librosa.feature.mfcc(
            y=y, 
            sr=sr, 
            n_mfcc=13,
            n_fft=self.n_fft,
            hop_length=self.hop_length
        )
        
        # Statistiques sur les MFCC
        mfcc_mean = np.mean(mfccs, axis=1)
        mfcc_std = np.std(mfccs, axis=1)
        
        return np.concatenate([mfcc_mean, mfcc_std])
    
    def _extract_tempo_features(self, y: np.ndarray, sr: int) -> Dict:
        """Extrait les features de tempo et rythme"""
        # Détection du tempo
        tempo, beats = librosa.beat.beat_track(y=y, sr=sr)
        
        # Onset detection
        onset_frames = librosa.onset.onset_detect(y=y, sr=sr)
        onset_times = librosa.onset.frames_to_time(onset_frames, sr=sr)
        
        return {
            "tempo": float(tempo),
            "beat_count": len(beats),
            "onset_count": len(onset_times),
            "rhythm_regularity": float(np.std(np.diff(beats))) if len(beats) > 1 else 0.0
        }
    
    def _generate_perceptual_hash(self, y: np.ndarray, sr: int) -> str:
        """Génère un hash perceptuel robuste"""
        # Spectrogram
        S = np.abs(librosa.stft(y, n_fft=self.n_fft, hop_length=self.hop_length))
        
        # Mel-scale spectrogram
        mel_spec = librosa.feature.melspectrogram(
            S=S**2, 
            sr=sr, 
            n_mels=self.n_mels
        )
        
        # Log-amplitude
        log_mel = librosa.power_to_db(mel_spec)
        
        # Réduction dimensionnelle pour hash
        # Moyenne temporelle
        mean_spectrum = np.mean(log_mel, axis=1)
        
        # Binarisation relative à la médiane
        median_val = np.median(mean_spectrum)
        binary_hash = (mean_spectrum > median_val).astype(int)
        
        # Conversion en string hexadécimal
        hash_bytes = np.packbits(binary_hash)
        return hashlib.sha256(hash_bytes.tobytes()).hexdigest()[:32]
    
    async def compare_fingerprints(
        self, 
        fp1: Dict, 
        fp2: Dict, 
        threshold: float = 0.8
    ) -> Dict:
        """
        Compare deux fingerprints audio
        
        Args:
            fp1, fp2: Fingerprints à comparer
            threshold: Seuil de similarité
            
        Returns:
            Dict avec scores de similarité
        """
        similarity_scores = {}
        
        # 1. Comparaison Chromaprint
        if fp1.get("chromaprint") and fp2.get("chromaprint"):
            chromaprint_sim = self._compare_chromaprint(
                fp1["chromaprint"], 
                fp2["chromaprint"]
            )
            similarity_scores["chromaprint"] = chromaprint_sim
        
        # 2. Comparaison features spectrales
        if fp1.get("spectral_features") and fp2.get("spectral_features"):
            spectral_sim = self._cosine_similarity(
                np.array(fp1["spectral_features"]),
                np.array(fp2["spectral_features"])
            )
            similarity_scores["spectral"] = float(spectral_sim)
        
        # 3. Comparaison MFCC
        if fp1.get("mfcc_features") and fp2.get("mfcc_features"):
            mfcc_sim = self._cosine_similarity(
                np.array(fp1["mfcc_features"]),
                np.array(fp2["mfcc_features"])
            )
            similarity_scores["mfcc"] = float(mfcc_sim)
        
        # 4. Comparaison hash perceptuel
        if fp1.get("perceptual_hash") and fp2.get("perceptual_hash"):
            hash_sim = self._hamming_similarity(
                fp1["perceptual_hash"],
                fp2["perceptual_hash"]
            )
            similarity_scores["perceptual_hash"] = hash_sim
        
        # Score global pondéré
        weights = {
            "chromaprint": 0.4,
            "spectral": 0.2,
            "mfcc": 0.2,
            "perceptual_hash": 0.2
        }
        
        global_score = sum(
            similarity_scores.get(key, 0) * weight 
            for key, weight in weights.items()
        )
        
        similarity_scores["global_score"] = global_score
        similarity_scores["is_match"] = global_score >= threshold
        
        return similarity_scores
    
    def _compare_chromaprint(self, fp1: str, fp2: str) -> float:
        """Compare deux fingerprints Chromaprint"""
        try:
            # Utilisation de la distance de Hamming normalisée
            if not fp1 or not fp2:
                return 0.0
                
            # Conversion en entiers pour comparaison bit à bit
            fp1_int = int(fp1, 16) if isinstance(fp1, str) else fp1
            fp2_int = int(fp2, 16) if isinstance(fp2, str) else fp2
            
            # XOR pour différences
            diff = fp1_int ^ fp2_int
            
            # Comptage des bits différents
            diff_bits = bin(diff).count('1')
            
            # Longueur maximale
            max_bits = max(fp1_int.bit_length(), fp2_int.bit_length())
            
            if max_bits == 0:
                return 1.0
                
            # Similarité = 1 - (différences / total)
            similarity = 1.0 - (diff_bits / max_bits)
            return max(0.0, similarity)
            
        except Exception:
            return 0.0
    
    def _cosine_similarity(self, vec1: np.ndarray, vec2: np.ndarray) -> float:
        """Calcule la similarité cosinus entre deux vecteurs"""
        try:
            # Normalisation
            vec1_norm = vec1 / (np.linalg.norm(vec1) + 1e-10)
            vec2_norm = vec2 / (np.linalg.norm(vec2) + 1e-10)
            
            # Produit scalaire
            similarity = np.dot(vec1_norm, vec2_norm)
            
            # Clamp entre 0 et 1
            return max(0.0, min(1.0, similarity))
            
        except Exception:
            return 0.0
    
    def _hamming_similarity(self, hash1: str, hash2: str) -> float:
        """Calcule la similarité de Hamming entre deux hashs"""
        try:
            if not hash1 or not hash2 or len(hash1) != len(hash2):
                return 0.0
                
            # Comptage des caractères identiques
            matches = sum(c1 == c2 for c1, c2 in zip(hash1, hash2))
            
            return matches / len(hash1)
            
        except Exception:
            return 0.0
    
    async def store_fingerprint(
        self, 
        user_id: int,
        content_id: str,
        fingerprint_data: Dict,
        metadata: Dict,
        db: Session
    ) -> AudioFingerprint:
        """Stocke le fingerprint en base de données"""
        try:
            audio_fingerprint = AudioFingerprint(
                user_id=user_id,
                content_id=content_id,
                chromaprint=fingerprint_data.get("chromaprint"),
                spectral_features=fingerprint_data.get("spectral_features"),
                mfcc_features=fingerprint_data.get("mfcc_features"),
                tempo_features=fingerprint_data.get("tempo_features"),
                perceptual_hash=fingerprint_data.get("perceptual_hash"),
                duration=fingerprint_data.get("duration"),
                sample_rate=fingerprint_data.get("sample_rate"),
                file_format=metadata.get("file_format"),
                file_size=metadata.get("file_size"),
                title=metadata.get("title", ""),
                artist=metadata.get("artist", "")
            )
            
            db.add(audio_fingerprint)
            db.commit()
            db.refresh(audio_fingerprint)
            
            return audio_fingerprint
            
        except Exception as e:
            db.rollback()
            raise Exception(f"Erreur stockage fingerprint: {str(e)}")
