"""
AI Video Fingerprinting Engine
Protection et identification de contenu vidéo pour créateurs
"""
import cv2
import numpy as np
import hashlib
from typing import Dict, List, Optional, Tuple
import tempfile
import os
from PIL import Image
import imagehash
from sqlalchemy.orm import Session
from app.models.orm.content_protection import VideoFingerprint
from app.services.ai.fingerprint_base import FingerprintBase


class VideoFingerprintEngine(FingerprintBase):
    """
    Moteur de fingerprinting vidéo avancé
    - Extraction de frames clés
    - Hashing perceptuel par frame
    - Détection d'objets via YOLO/MobileNet
    - Analyse de mouvement et transitions
    """
    
    def __init__(self):
        self.frame_sample_rate = 1.0  # 1 frame par seconde
        self.max_frames = 100  # Limite pour optimiser les performances
        self.hash_size = 16   # Taille des hashs perceptuels
        
    async def extract_fingerprint(self, video_path: str) -> Dict:
        """
        Extrait le fingerprint vidéo multi-algorithmes
        
        Args:
            video_path: Chemin vers le fichier vidéo
            
        Returns:
            Dict contenant tous les fingerprints
        """
        try:
            # Ouverture de la vidéo avec OpenCV
            cap = cv2.VideoCapture(video_path)
            
            if not cap.isOpened():
                raise Exception(f"Impossible d'ouvrir la vidéo: {video_path}")
            
            # Métadonnées vidéo
            fps = cap.get(cv2.CAP_PROP_FPS)
            frame_count = int(cap.get(cv2.CAP_PROP_FRAME_COUNT))
            duration = frame_count / fps if fps > 0 else 0
            width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
            height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
            
            # 1. Extraction des frames clés
            key_frames = await self._extract_key_frames(cap, fps)
            
            # 2. Hashing perceptuel des frames
            frame_hashes = self._generate_frame_hashes(key_frames)
            
            # 3. Analyse de mouvement
            motion_features = self._analyze_motion(key_frames)
            
            # 4. Détection de transitions
            transition_features = self._detect_transitions(key_frames)
            
            # 5. Analyse colorimétrique
            color_features = self._analyze_colors(key_frames)
            
            # 6. Hash global de la vidéo
            global_hash = self._generate_global_hash(frame_hashes, motion_features)
            
            cap.release()
            
            fingerprint_data = {
                "frame_hashes": frame_hashes,
                "motion_features": motion_features,
                "transition_features": transition_features,
                "color_features": color_features,
                "global_hash": global_hash,
                "metadata": {
                    "duration": duration,
                    "fps": fps,
                    "frame_count": frame_count,
                    "resolution": f"{width}x{height}",
                    "key_frame_count": len(key_frames)
                }
            }
            
            return fingerprint_data
            
        except Exception as e:
            raise Exception(f"Erreur extraction fingerprint vidéo: {str(e)}")
    
    async def _extract_key_frames(self, cap: cv2.VideoCapture, fps: float) -> List[np.ndarray]:
        """Extrait les frames clés de la vidéo"""
        key_frames = []
        frame_interval = max(1, int(fps / self.frame_sample_rate))
        frame_index = 0
        
        while len(key_frames) < self.max_frames:
            ret, frame = cap.read()
            if not ret:
                break
                
            if frame_index % frame_interval == 0:
                # Redimensionnement pour optimiser les performances
                frame_resized = cv2.resize(frame, (256, 256))
                key_frames.append(frame_resized)
            
            frame_index += 1
        
        return key_frames
    
    def _generate_frame_hashes(self, frames: List[np.ndarray]) -> List[str]:
        """Génère les hashs perceptuels pour chaque frame"""
        frame_hashes = []
        
        for frame in frames:
            # Conversion BGR vers RGB pour PIL
            frame_rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
            pil_image = Image.fromarray(frame_rgb)
            
            # Génération de plusieurs types de hashs
            dhash = str(imagehash.dhash(pil_image, hash_size=self.hash_size))
            phash = str(imagehash.phash(pil_image, hash_size=self.hash_size))
            ahash = str(imagehash.average_hash(pil_image, hash_size=self.hash_size))
            
            # Hash combiné
            combined_hash = hashlib.sha256(
                f"{dhash}{phash}{ahash}".encode()
            ).hexdigest()[:32]
            
            frame_hashes.append({
                "dhash": dhash,
                "phash": phash,
                "ahash": ahash,
                "combined": combined_hash
            })
        
        return frame_hashes
    
    def _analyze_motion(self, frames: List[np.ndarray]) -> Dict:
        """Analyse les caractéristiques de mouvement"""
        if len(frames) < 2:
            return {"motion_intensity": 0.0, "motion_patterns": []}
        
        motion_scores = []
        motion_vectors = []
        
        for i in range(1, len(frames)):
            prev_frame = cv2.cvtColor(frames[i-1], cv2.COLOR_BGR2GRAY)
            curr_frame = cv2.cvtColor(frames[i], cv2.COLOR_BGR2GRAY)
            
            # Calcul du flux optique
            flow = cv2.calcOpticalFlowPyrLK(
                prev_frame, curr_frame,
                corners=cv2.goodFeaturesToTrack(prev_frame, 100, 0.3, 7),
                winSize=(15, 15),
                maxLevel=2,
                criteria=(cv2.TERM_CRITERIA_EPS | cv2.TERM_CRITERIA_COUNT, 10, 0.03)
            )[0]
            
            if flow is not None and len(flow) > 0:
                # Intensité de mouvement
                motion_magnitude = np.mean(np.linalg.norm(flow, axis=1))
                motion_scores.append(float(motion_magnitude))
                
                # Direction dominante
                angles = np.arctan2(flow[:, 1], flow[:, 0])
                dominant_angle = float(np.mean(angles))
                motion_vectors.append(dominant_angle)
            else:
                motion_scores.append(0.0)
                motion_vectors.append(0.0)
        
        return {
            "motion_intensity": float(np.mean(motion_scores)),
            "motion_variance": float(np.var(motion_scores)),
            "dominant_directions": motion_vectors[:10],  # Limitation pour stockage
            "scene_changes": len([s for s in motion_scores if s > np.mean(motion_scores) + np.std(motion_scores)])
        }
    
    def _detect_transitions(self, frames: List[np.ndarray]) -> Dict:
        """Détecte les transitions et coupures dans la vidéo"""
        if len(frames) < 2:
            return {"transition_points": [], "transition_types": []}
        
        transition_points = []
        transition_types = []
        
        for i in range(1, len(frames)):
            prev_frame = frames[i-1]
            curr_frame = frames[i]
            
            # Comparaison histogramme de couleurs
            hist_prev = cv2.calcHist([prev_frame], [0, 1, 2], None, [8, 8, 8], [0, 256, 0, 256, 0, 256])
            hist_curr = cv2.calcHist([curr_frame], [0, 1, 2], None, [8, 8, 8], [0, 256, 0, 256, 0, 256])
            
            # Corrélation des histogrammes
            correlation = cv2.compareHist(hist_prev, hist_curr, cv2.HISTCMP_CORREL)
            
            # Détection de transition (faible corrélation)
            if correlation < 0.7:
                transition_points.append(i)
                
                # Type de transition basé sur le niveau de corrélation
                if correlation < 0.3:
                    transition_types.append("cut")
                elif correlation < 0.5:
                    transition_types.append("fade")
                else:
                    transition_types.append("gradual")
        
        return {
            "transition_points": transition_points,
            "transition_types": transition_types,
            "transition_count": len(transition_points)
        }
    
    def _analyze_colors(self, frames: List[np.ndarray]) -> Dict:
        """Analyse les caractéristiques colorimétriques"""
        if not frames:
            return {"dominant_colors": [], "color_variance": 0.0}
        
        # Échantillonnage de frames pour l'analyse
        sample_frames = frames[::max(1, len(frames) // 10)]
        
        all_colors = []
        color_variances = []
        
        for frame in sample_frames:
            # Conversion en Lab pour une meilleure analyse colorimétrique
            lab_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2LAB)
            
            # Extraction des couleurs dominantes via K-means
            pixels = lab_frame.reshape(-1, 3).astype(np.float32)
            
            # K-means pour identifier les couleurs dominantes
            criteria = (cv2.TERM_CRITERIA_EPS + cv2.TERM_CRITERIA_MAX_ITER, 100, 0.2)
            _, labels, centers = cv2.kmeans(
                pixels, 5, None, criteria, 10, cv2.KMEANS_RANDOM_CENTERS
            )
            
            # Conversion des centres en couleurs RGB
            centers_bgr = cv2.cvtColor(
                centers.reshape(1, -1, 3).astype(np.uint8), 
                cv2.COLOR_LAB2BGR
            ).reshape(-1, 3)
            
            all_colors.extend(centers_bgr.tolist())
            
            # Variance colorimétrique
            color_variance = float(np.var(pixels))
            color_variances.append(color_variance)
        
        # Couleurs dominantes globales
        if all_colors:
            all_colors_array = np.array(all_colors, dtype=np.float32)
            criteria = (cv2.TERM_CRITERIA_EPS + cv2.TERM_CRITERIA_MAX_ITER, 100, 0.2)
            _, _, global_centers = cv2.kmeans(
                all_colors_array, 3, None, criteria, 10, cv2.KMEANS_RANDOM_CENTERS
            )
            dominant_colors = global_centers.astype(int).tolist()
        else:
            dominant_colors = []
        
        return {
            "dominant_colors": dominant_colors,
            "color_variance": float(np.mean(color_variances)),
            "color_complexity": len(set(tuple(color) for color in all_colors[:50]))
        }
    
    def _generate_global_hash(self, frame_hashes: List[Dict], motion_features: Dict) -> str:
        """Génère un hash global pour toute la vidéo"""
        # Concaténation des hashs de frames
        combined_hashes = []
        for fh in frame_hashes[:20]:  # Limitation à 20 frames pour performance
            combined_hashes.append(fh.get("combined", ""))
        
        # Ajout des features de mouvement
        motion_str = f"{motion_features.get('motion_intensity', 0):.3f}"
        
        # Hash final
        full_string = "".join(combined_hashes) + motion_str
        return hashlib.sha256(full_string.encode()).hexdigest()[:64]
    
    async def compare_fingerprints(
        self, 
        fp1: Dict, 
        fp2: Dict, 
        threshold: float = 0.75
    ) -> Dict:
        """
        Compare deux fingerprints vidéo
        
        Args:
            fp1, fp2: Fingerprints à comparer
            threshold: Seuil de similarité
            
        Returns:
            Dict avec scores de similarité
        """
        similarity_scores = {}
        
        # 1. Comparaison des hashs de frames
        if fp1.get("frame_hashes") and fp2.get("frame_hashes"):
            frame_similarity = self._compare_frame_hashes(
                fp1["frame_hashes"],
                fp2["frame_hashes"]
            )
            similarity_scores["frames"] = frame_similarity
        
        # 2. Comparaison des features de mouvement
        if fp1.get("motion_features") and fp2.get("motion_features"):
            motion_similarity = self._compare_motion_features(
                fp1["motion_features"],
                fp2["motion_features"]
            )
            similarity_scores["motion"] = motion_similarity
        
        # 3. Comparaison des transitions
        if fp1.get("transition_features") and fp2.get("transition_features"):
            transition_similarity = self._compare_transitions(
                fp1["transition_features"],
                fp2["transition_features"]
            )
            similarity_scores["transitions"] = transition_similarity
        
        # 4. Comparaison colorimétrique
        if fp1.get("color_features") and fp2.get("color_features"):
            color_similarity = self._compare_colors(
                fp1["color_features"],
                fp2["color_features"]
            )
            similarity_scores["colors"] = color_similarity
        
        # 5. Comparaison hash global
        if fp1.get("global_hash") and fp2.get("global_hash"):
            hash_similarity = self._hamming_similarity(
                fp1["global_hash"],
                fp2["global_hash"]
            )
            similarity_scores["global_hash"] = hash_similarity
        
        # Score global pondéré
        weights = {
            "frames": 0.4,
            "motion": 0.2,
            "transitions": 0.15,
            "colors": 0.15,
            "global_hash": 0.1
        }
        
        global_score = sum(
            similarity_scores.get(key, 0) * weight 
            for key, weight in weights.items()
        )
        
        similarity_scores["global_score"] = global_score
        similarity_scores["is_match"] = global_score >= threshold
        
        return similarity_scores
    
    def _compare_frame_hashes(self, hashes1: List[Dict], hashes2: List[Dict]) -> float:
        """Compare les hashs de frames entre deux vidéos"""
        if not hashes1 or not hashes2:
            return 0.0
        
        # Comparaison avec fenêtre glissante pour gérer les décalages temporels
        max_similarity = 0.0
        window_size = min(len(hashes1), len(hashes2), 10)
        
        for offset in range(-2, 3):  # Tolérance de décalage
            similarities = []
            
            for i in range(window_size):
                idx1 = i
                idx2 = i + offset
                
                if 0 <= idx2 < len(hashes2):
                    hash1 = hashes1[idx1]
                    hash2 = hashes2[idx2]
                    
                    # Comparaison des différents types de hashs
                    dhash_sim = self._hamming_similarity(
                        hash1.get("dhash", ""), 
                        hash2.get("dhash", "")
                    )
                    phash_sim = self._hamming_similarity(
                        hash1.get("phash", ""), 
                        hash2.get("phash", "")
                    )
                    ahash_sim = self._hamming_similarity(
                        hash1.get("ahash", ""), 
                        hash2.get("ahash", "")
                    )
                    
                    # Moyenne pondérée
                    frame_sim = (dhash_sim * 0.4 + phash_sim * 0.4 + ahash_sim * 0.2)
                    similarities.append(frame_sim)
            
            if similarities:
                avg_similarity = np.mean(similarities)
                max_similarity = max(max_similarity, avg_similarity)
        
        return max_similarity
    
    def _compare_motion_features(self, motion1: Dict, motion2: Dict) -> float:
        """Compare les features de mouvement"""
        try:
            # Comparaison de l'intensité de mouvement
            intensity1 = motion1.get("motion_intensity", 0)
            intensity2 = motion2.get("motion_intensity", 0)
            
            max_intensity = max(intensity1, intensity2, 1.0)
            intensity_sim = 1.0 - abs(intensity1 - intensity2) / max_intensity
            
            # Comparaison de la variance
            variance1 = motion1.get("motion_variance", 0)
            variance2 = motion2.get("motion_variance", 0)
            
            max_variance = max(variance1, variance2, 1.0)
            variance_sim = 1.0 - abs(variance1 - variance2) / max_variance
            
            # Comparaison des changements de scène
            changes1 = motion1.get("scene_changes", 0)
            changes2 = motion2.get("scene_changes", 0)
            
            max_changes = max(changes1, changes2, 1)
            changes_sim = 1.0 - abs(changes1 - changes2) / max_changes
            
            # Moyenne pondérée
            return (intensity_sim * 0.5 + variance_sim * 0.3 + changes_sim * 0.2)
            
        except Exception:
            return 0.0
    
    def _compare_transitions(self, trans1: Dict, trans2: Dict) -> float:
        """Compare les patterns de transitions"""
        try:
            count1 = trans1.get("transition_count", 0)
            count2 = trans2.get("transition_count", 0)
            
            if count1 == 0 and count2 == 0:
                return 1.0
            
            max_count = max(count1, count2, 1)
            count_sim = 1.0 - abs(count1 - count2) / max_count
            
            # Comparaison des types de transitions
            types1 = trans1.get("transition_types", [])
            types2 = trans2.get("transition_types", [])
            
            if types1 and types2:
                common_types = set(types1) & set(types2)
                all_types = set(types1) | set(types2)
                type_sim = len(common_types) / len(all_types) if all_types else 0.0
            else:
                type_sim = 1.0 if not types1 and not types2 else 0.0
            
            return (count_sim * 0.6 + type_sim * 0.4)
            
        except Exception:
            return 0.0
    
    def _compare_colors(self, colors1: Dict, colors2: Dict) -> float:
        """Compare les caractéristiques colorimétriques"""
        try:
            # Comparaison des couleurs dominantes
            dom_colors1 = colors1.get("dominant_colors", [])
            dom_colors2 = colors2.get("dominant_colors", [])
            
            if not dom_colors1 and not dom_colors2:
                return 1.0
            elif not dom_colors1 or not dom_colors2:
                return 0.0
            
            # Distance euclidienne minimale entre couleurs
            min_distances = []
            for color1 in dom_colors1:
                distances = [
                    np.linalg.norm(np.array(color1) - np.array(color2))
                    for color2 in dom_colors2
                ]
                min_distances.append(min(distances))
            
            avg_distance = np.mean(min_distances)
            # Normalisation (distance max RGB = sqrt(3*255^2))
            color_similarity = max(0.0, 1.0 - avg_distance / 441.67)
            
            # Comparaison de la variance colorimétrique
            variance1 = colors1.get("color_variance", 0)
            variance2 = colors2.get("color_variance", 0)
            
            max_variance = max(variance1, variance2, 1.0)
            variance_sim = 1.0 - abs(variance1 - variance2) / max_variance
            
            return (color_similarity * 0.7 + variance_sim * 0.3)
            
        except Exception:
            return 0.0
    
    def _hamming_similarity(self, hash1: str, hash2: str) -> float:
        """Calcule la similarité de Hamming entre deux hashs"""
        try:
            if not hash1 or not hash2 or len(hash1) != len(hash2):
                return 0.0
                
            matches = sum(c1 == c2 for c1, c2 in zip(hash1, hash2))
            return matches / len(hash1)
            
        except Exception:
            return 0.0
    
    async def store_fingerprint(
        self, 
        user_id: int,
        content_id: str,
        fingerprint_data: Dict,
        metadata: Dict,
        db: Session
    ) -> VideoFingerprint:
        """Stocke le fingerprint en base de données"""
        try:
            video_fingerprint = VideoFingerprint(
                user_id=user_id,
                content_id=content_id,
                frame_hashes=fingerprint_data.get("frame_hashes"),
                motion_features=fingerprint_data.get("motion_features"),
                transition_features=fingerprint_data.get("transition_features"),
                color_features=fingerprint_data.get("color_features"),
                global_hash=fingerprint_data.get("global_hash"),
                duration=fingerprint_data.get("metadata", {}).get("duration"),
                fps=fingerprint_data.get("metadata", {}).get("fps"),
                resolution=fingerprint_data.get("metadata", {}).get("resolution"),
                frame_count=fingerprint_data.get("metadata", {}).get("frame_count"),
                file_format=metadata.get("file_format"),
                file_size=metadata.get("file_size"),
                title=metadata.get("title", ""),
                description=metadata.get("description", "")
            )
            
            db.add(video_fingerprint)
            db.commit()
            db.refresh(video_fingerprint)
            
            return video_fingerprint
            
        except Exception as e:
            db.rollback()
            raise Exception(f"Erreur stockage fingerprint vidéo: {str(e)}")
