logger = structlog.get_logger(__name__)


@dataclass
class ProcessorConfig:
    """Configuration for data processors."""
    batch_size: int = 1000
    max_workers: int = 10
    timeout_seconds: int = 30
    retry_attempts: int = 3
    enable_compression: bool = True
    enable_encryption: bool = True
    buffer_size: int = 10000
    flush_interval: int = 5


class StreamProcessor:
    """
    Ultra-advanced stream processor for real-time data processing
    with microsecond latency and unlimited scalability.
    """
    
    def __init__(self, config: ProcessorConfig):
        self.config = config
        self.stream_id = str(uuid.uuid4())
        self.processing_pipeline = []
        self.stream_buffer = deque(maxsize=config.buffer_size)
        self.metrics = {
            "events_processed": 0,
            "avg_latency_us": 0.0,
            "throughput_per_second": 0.0,
            "errors": 0
        }
        self.is_running = False
        
    async def initialize(self) -> None:
        """Initialize the stream processor."""
        try:
            logger.info(f"Initializing StreamProcessor {self.stream_id}")
            
            # Initialize processing pipeline
            await self._setup_processing_pipeline()
            
            # Start processing workers
            asyncio.create_task(self._stream_processing_worker())
            asyncio.create_task(self._metrics_collection_worker())
            
            self.is_running = True
            logger.info(f"StreamProcessor {self.stream_id} initialized successfully")
            
        except Exception as e:
            logger.error(f"Failed to initialize StreamProcessor: {e}")
            raise
    
    async def process_event(self, event: Dict[str, Any]) -> Dict[str, Any]:
        """Process a single event through the stream."""
        try:
            start_time = time.perf_counter()
            
            # Add timestamp if not present
            if "timestamp" not in event:
                event["timestamp"] = datetime.now(timezone.utc).isoformat()
            
            # Add to buffer for async processing
            if len(self.stream_buffer) < self.config.buffer_size:
                self.stream_buffer.append(event)
            
            # Process through pipeline stages
            processed_event = await self._process_through_pipeline(event)
            
            # Calculate latency in microseconds
            latency_us = (time.perf_counter() - start_time) * 1_000_000
            
            # Update metrics
            self.metrics["events_processed"] += 1
            self.metrics["avg_latency_us"] = (
                self.metrics["avg_latency_us"] * 0.95 + latency_us * 0.05
            )
            
            return {
                "status": "processed",
                "event_id": processed_event.get("id", str(uuid.uuid4())),
                "latency_us": latency_us,
                "result": processed_event
            }
            
        except Exception as e:
            self.metrics["errors"] += 1
            logger.error(f"Error processing event: {e}")
            return {
                "status": "error",
                "error": str(e),
                "event": event
            }
    
    async def add_processor(self, processor_func: Callable) -> None:
        """Add a processor function to the pipeline."""
        self.processing_pipeline.append(processor_func)
        logger.debug(f"Added processor to pipeline: {processor_func.__name__}")
    
    async def health_check(self) -> Dict[str, Any]:
        """Health check for the stream processor."""
        return {
            "healthy": self.is_running,
            "stream_id": self.stream_id,
            "buffer_size": len(self.stream_buffer),
            "pipeline_stages": len(self.processing_pipeline),
            "metrics": self.metrics
        }
    
    async def get_stream_analytics(self) -> Dict[str, Any]:
        """Get comprehensive stream analytics."""
        return {
            "stream_id": self.stream_id,
            "processing_metrics": self.metrics,
            "pipeline_info": {
                "stages": len(self.processing_pipeline),
                "buffer_utilization": len(self.stream_buffer) / self.config.buffer_size
            },
            "performance_stats": {
                "avg_latency_ms": self.metrics["avg_latency_us"] / 1000,
                "throughput_per_second": self.metrics["throughput_per_second"],
                "error_rate": self.metrics["errors"] / max(1, self.metrics["events_processed"])
            }
        }
    
    # ================== PRIVATE METHODS ==================
    
    async def _setup_processing_pipeline(self) -> None:
        """Setup the processing pipeline."""
        # Add default processors
        await self.add_processor(self._validate_event)
        await self.add_processor(self._enrich_event)
        await self.add_processor(self._transform_event)
    
    async def _process_through_pipeline(self, event: Dict[str, Any]) -> Dict[str, Any]:
        """Process event through all pipeline stages."""
        current_event = event.copy()
        
        for processor in self.processing_pipeline:
            try:
                current_event = await processor(current_event)
                if not current_event:
                    raise ValueError("Processor returned empty result")
            except Exception as e:
                logger.error(f"Error in pipeline processor {processor.__name__}: {e}")
                current_event["pipeline_error"] = str(e)
        
        return current_event
    
    async def _validate_event(self, event: Dict[str, Any]) -> Dict[str, Any]:
        """Validate event structure and data."""
        required_fields = ["timestamp"]
        
        for field in required_fields:
            if field not in event:
                event[field] = self._get_default_value(field)
        
        event["validated"] = True
        return event
    
    async def _enrich_event(self, event: Dict[str, Any]) -> Dict[str, Any]:
        """Enrich event with additional metadata."""
        event["processing_info"] = {
            "processor_id": self.stream_id,
            "processed_at": datetime.now(timezone.utc).isoformat(),
            "enriched": True
        }
        return event
    
    async def _transform_event(self, event: Dict[str, Any]) -> Dict[str, Any]:
        """Transform event data."""
        # Add unique event ID if not present
        if "id" not in event:
            event["id"] = str(uuid.uuid4())
        
        event["transformed"] = True
        return event
    
    def _get_default_value(self, field: str) -> Any:
        """Get default value for missing field."""
        defaults = {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "id": str(uuid.uuid4())
        }
        return defaults.get(field, None)
    
    async def _stream_processing_worker(self) -> None:
        """Background worker for stream processing."""
        while self.is_running:
            try:
                # Process buffered events
                processed_count = 0
                start_time = time.time()
                
                while self.stream_buffer and processed_count < 100:
                    event = self.stream_buffer.popleft()
                    await self._process_buffered_event(event)
                    processed_count += 1
                
                # Update throughput
                if processed_count > 0:
                    elapsed = time.time() - start_time
                    throughput = processed_count / max(elapsed, 0.001)
                    self.metrics["throughput_per_second"] = (
                        self.metrics["throughput_per_second"] * 0.9 + throughput * 0.1
                    )
                
                await asyncio.sleep(0.01)  # 10ms interval for high-frequency processing
                
            except Exception as e:
                logger.error(f"Error in stream processing worker: {e}")
                await asyncio.sleep(1)
    
    async def _process_buffered_event(self, event: Dict[str, Any]) -> None:
        """Process a buffered event."""
        # Additional processing for buffered events
        pass
    
    async def _metrics_collection_worker(self) -> None:
        """Background worker for metrics collection."""
        while self.is_running:
            try:
                # Collect and log metrics
                await self._collect_stream_metrics()
                await asyncio.sleep(30)  # Collect metrics every 30 seconds
            except Exception as e:
                logger.error(f"Error in metrics collection: {e}")
                await asyncio.sleep(30)
    
    async def _collect_stream_metrics(self) -> None:
        """Collect comprehensive stream metrics."""
        # Log current metrics
        logger.info(
            "Stream metrics",
            stream_id=self.stream_id,
            events_processed=self.metrics["events_processed"],
            avg_latency_us=self.metrics["avg_latency_us"],
            throughput_per_second=self.metrics["throughput_per_second"]
        )


class BatchProcessor:
    """
    Ultra-advanced batch processor for large-scale data processing
    with distributed computing capabilities and intelligent optimization.
    """
    
    def __init__(self, config: ProcessorConfig):
        self.config = config
        self.processor_id = str(uuid.uuid4())
        self.batch_queue = asyncio.Queue(maxsize=1000)
        self.processing_jobs = {}
        self.executor = ProcessPoolExecutor(max_workers=config.max_workers)
        self.metrics = {
            "batches_processed": 0,
            "total_items_processed": 0,
            "avg_batch_time": 0.0,
            "errors": 0
        }
        
    async def initialize(self) -> None:
        """Initialize the batch processor."""
        try:
            logger.info(f"Initializing BatchProcessor {self.processor_id}")
            
            # Start batch processing worker
            asyncio.create_task(self._batch_processing_worker())
            
            logger.info(f"BatchProcessor {self.processor_id} initialized successfully")
            
        except Exception as e:
            logger.error(f"Failed to initialize BatchProcessor: {e}")
            raise
    
    async def submit_batch(self, data: List[Any], operation: str = "process") -> str:
        """Submit a batch for processing."""
        try:
            job_id = str(uuid.uuid4())
            batch_job = {
                "job_id": job_id,
                "data": data,
                "operation": operation,
                "submitted_at": datetime.now(timezone.utc),
                "status": "queued",
                "size": len(data)
            }
            
            await self.batch_queue.put(batch_job)
            self.processing_jobs[job_id] = batch_job
            
            logger.debug(f"Batch job submitted: {job_id}, size: {len(data)}")
            return job_id
            
        except Exception as e:
            logger.error(f"Error submitting batch: {e}")
            raise
    
    async def get_job_status(self, job_id: str) -> Optional[Dict[str, Any]]:
        """Get status of a batch job."""
        return self.processing_jobs.get(job_id)
    
    async def process_batch_sync(self, data: List[Any], operation: str = "process") -> Dict[str, Any]:
        """Process batch synchronously and return results."""
        try:
            start_time = time.time()
            
            # Split into optimal chunks
            chunks = self._create_optimal_chunks(data)
            
            # Process chunks in parallel
            tasks = [
                self._process_chunk(chunk, operation)
                for chunk in chunks
            ]
            
            chunk_results = await asyncio.gather(*tasks, return_exceptions=True)
            
            # Aggregate results
            all_results = []
            errors = []
            
            for result in chunk_results:
                if isinstance(result, Exception):
                    errors.append(str(result))
                else:
                    all_results.extend(result)
            
            processing_time = time.time() - start_time
            
            # Update metrics
            self.metrics["batches_processed"] += 1
            self.metrics["total_items_processed"] += len(data)
            self.metrics["avg_batch_time"] = (
                self.metrics["avg_batch_time"] * 0.9 + processing_time * 0.1
            )
            
            if errors:
                self.metrics["errors"] += len(errors)
            
            return {
                "status": "completed",
                "results": all_results,
                "errors": errors,
                "processing_time": processing_time,
                "items_processed": len(data),
                "success_rate": len(all_results) / len(data) if data else 1.0
            }
            
        except Exception as e:
            self.metrics["errors"] += 1
            logger.error(f"Error in batch processing: {e}")
            return {
                "status": "error",
                "error": str(e)
            }
    
    async def health_check(self) -> Dict[str, Any]:
        """Health check for the batch processor."""
        return {
            "healthy": True,
            "processor_id": self.processor_id,
            "queue_size": self.batch_queue.qsize(),
            "active_jobs": len([job for job in self.processing_jobs.values() 
                              if job["status"] in ["queued", "processing"]]),
            "metrics": self.metrics
        }
    
    # ================== PRIVATE METHODS ==================
    
    def _create_optimal_chunks(self, data: List[Any]) -> List[List[Any]]:
        """Create optimal chunks for parallel processing."""
        chunk_size = max(1, len(data) // self.config.max_workers)
        chunks = []
        
        for i in range(0, len(data), chunk_size):
            chunks.append(data[i:i + chunk_size])
        
        return chunks
    
    async def _process_chunk(self, chunk: List[Any], operation: str) -> List[Any]:
        """Process a chunk of data."""
        try:
            # Process each item in the chunk
            results = []
            for item in chunk:
                processed_item = await self._process_single_item(item, operation)
                results.append(processed_item)
            
            return results
            
        except Exception as e:
            logger.error(f"Error processing chunk: {e}")
            raise
    
    async def _process_single_item(self, item: Any, operation: str) -> Any:
        """Process a single item."""
        try:
            if operation == "validate":
                return await self._validate_item(item)
            elif operation == "transform":
                return await self._transform_item(item)
            elif operation == "analyze":
                return await self._analyze_item(item)
            else:
                # Default processing
                return {
                    "original": item,
                    "processed": True,
                    "timestamp": datetime.now(timezone.utc).isoformat()
                }
                
        except Exception as e:
            logger.error(f"Error processing item: {e}")
            return {
                "original": item,
                "error": str(e),
                "processed": False
            }
    
    async def _validate_item(self, item: Any) -> Dict[str, Any]:
        """Validate a single item."""
        return {
            "item": item,
            "valid": True,
            "validation_timestamp": datetime.now(timezone.utc).isoformat()
        }
    
    async def _transform_item(self, item: Any) -> Dict[str, Any]:
        """Transform a single item."""
        return {
            "original": item,
            "transformed": str(item).upper() if isinstance(item, str) else item,
            "transform_timestamp": datetime.now(timezone.utc).isoformat()
        }
    
    async def _analyze_item(self, item: Any) -> Dict[str, Any]:
        """Analyze a single item."""
        analysis = {
            "type": type(item).__name__,
            "size": len(str(item)),
            "analysis_timestamp": datetime.now(timezone.utc).isoformat()
        }
        
        if isinstance(item, (int, float)):
            analysis["numeric_properties"] = {
                "value": item,
                "is_positive": item > 0,
                "is_integer": isinstance(item, int)
            }
        elif isinstance(item, str):
            analysis["string_properties"] = {
                "length": len(item),
                "word_count": len(item.split()),
                "is_uppercase": item.isupper(),
                "is_lowercase": item.islower()
            }
        
        return {
            "item": item,
            "analysis": analysis
        }
    
    async def _batch_processing_worker(self) -> None:
        """Background worker for batch processing."""
        while True:
            try:
                # Get batch job from queue
                batch_job = await asyncio.wait_for(self.batch_queue.get(), timeout=5.0)
                
                # Process the batch
                await self._process_batch_job(batch_job)
                
            except asyncio.TimeoutError:
                # No jobs in queue, continue
                continue
            except Exception as e:
                logger.error(f"Error in batch processing worker: {e}")
                await asyncio.sleep(5)
    
    async def _process_batch_job(self, batch_job: Dict[str, Any]) -> None:
        """Process a batch job."""
        try:
            job_id = batch_job["job_id"]
            data = batch_job["data"]
            operation = batch_job["operation"]
            
            # Update job status
            self.processing_jobs[job_id]["status"] = "processing"
            self.processing_jobs[job_id]["started_at"] = datetime.now(timezone.utc)
            
            # Process the batch
            result = await self.process_batch_sync(data, operation)
            
            # Update job with results
            self.processing_jobs[job_id].update({
                "status": "completed",
                "result": result,
                "completed_at": datetime.now(timezone.utc)
            })
            
            logger.info(f"Batch job completed: {job_id}")
            
        except Exception as e:
            # Update job with error
            self.processing_jobs[batch_job["job_id"]].update({
                "status": "failed",
                "error": str(e),
                "failed_at": datetime.now(timezone.utc)
            })
            logger.error(f"Batch job failed: {batch_job['job_id']}, error: {e}")


class EventProcessor:
    """
    Advanced event processor for complex event processing (CEP)
    with pattern matching and real-time alerting capabilities.
    """
    
    def __init__(self, config: ProcessorConfig):
        self.config = config
        self.processor_id = str(uuid.uuid4())
        self.event_buffer = deque(maxsize=config.buffer_size)
        self.patterns = {}
        self.triggers = {}
        self.metrics = {
            "events_received": 0,
            "patterns_matched": 0,
            "alerts_triggered": 0
        }
        
    async def initialize(self) -> None:
        """Initialize the event processor."""
        try:
            logger.info(f"Initializing EventProcessor {self.processor_id}")
            
            # Setup default patterns
            await self._setup_default_patterns()
            
            # Start event processing
            asyncio.create_task(self._event_processing_worker())
            
            logger.info(f"EventProcessor {self.processor_id} initialized successfully")
            
        except Exception as e:
            logger.error(f"Failed to initialize EventProcessor: {e}")
            raise
    
    async def process_event(self, event: Dict[str, Any]) -> Dict[str, Any]:
        """Process an event and check for pattern matches."""
        try:
            # Add timestamp if not present
            if "timestamp" not in event:
                event["timestamp"] = datetime.now(timezone.utc)
            
            # Add to buffer
            if len(self.event_buffer) >= self.config.buffer_size:
                self.event_buffer.popleft()  # Remove oldest
            
            self.event_buffer.append(event)
            self.metrics["events_received"] += 1
            
            # Check for pattern matches
            matches = await self._check_patterns(event)
            
            # Trigger alerts if patterns matched
            alerts = []
            for pattern_id, match_data in matches.items():
                alert = await self._trigger_alert(pattern_id, match_data, event)
                if alert:
                    alerts.append(alert)
            
            return {
                "event_processed": True,
                "patterns_matched": list(matches.keys()),
                "alerts_triggered": alerts,
                "buffer_size": len(self.event_buffer)
            }
            
        except Exception as e:
            logger.error(f"Error processing event: {e}")
            return {
                "event_processed": False,
                "error": str(e)
            }
    
    async def add_pattern(
        self,
        pattern_id: str,
        pattern_config: Dict[str, Any]
    ) -> None:
        """Add a new event pattern to monitor."""
        self.patterns[pattern_id] = {
            "config": pattern_config,
            "created_at": datetime.now(timezone.utc),
            "matches": 0
        }
        logger.info(f"Added event pattern: {pattern_id}")
    
    async def add_trigger(
        self,
        trigger_id: str,
        pattern_id: str,
        action: Callable
    ) -> None:
        """Add a trigger action for a pattern."""
        self.triggers[trigger_id] = {
            "pattern_id": pattern_id,
            "action": action,
            "created_at": datetime.now(timezone.utc),
            "executions": 0
        }
        logger.info(f"Added trigger: {trigger_id} for pattern: {pattern_id}")
    
    async def health_check(self) -> Dict[str, Any]:
        """Health check for the event processor."""
        return {
            "healthy": True,
            "processor_id": self.processor_id,
            "buffer_size": len(self.event_buffer),
            "patterns_count": len(self.patterns),
            "triggers_count": len(self.triggers),
            "metrics": self.metrics
        }
    
    # ================== PRIVATE METHODS ==================
    
    async def _setup_default_patterns(self) -> None:
        """Setup default event patterns."""
        # High frequency pattern
        await self.add_pattern("high_frequency", {
            "type": "frequency",
            "threshold": 100,
            "window_seconds": 60,
            "field": "event_type"
        })
        
        # Error rate pattern
        await self.add_pattern("error_spike", {
            "type": "error_rate",
            "threshold": 0.1,
            "window_seconds": 300,
            "error_field": "status",
            "error_values": ["error", "failed"]
        })
        
        # Anomaly pattern
        await self.add_pattern("value_anomaly", {
            "type": "anomaly",
            "field": "value",
            "threshold_stddev": 3.0,
            "window_size": 100
        })
    
    async def _check_patterns(self, event: Dict[str, Any]) -> Dict[str, Any]:
        """Check if event matches any patterns."""
        matches = {}
        
        for pattern_id, pattern_info in self.patterns.items():
            pattern_config = pattern_info["config"]
            
            if await self._matches_pattern(event, pattern_config):
                matches[pattern_id] = {
                    "matched_at": datetime.now(timezone.utc),
                    "event": event,
                    "pattern_config": pattern_config
                }
                
                # Update pattern match count
                self.patterns[pattern_id]["matches"] += 1
                self.metrics["patterns_matched"] += 1
        
        return matches
    
    async def _matches_pattern(
        self,
        event: Dict[str, Any],
        pattern_config: Dict[str, Any]
    ) -> bool:
        """Check if event matches a specific pattern."""
        try:
            pattern_type = pattern_config.get("type")
            
            if pattern_type == "frequency":
                return await self._check_frequency_pattern(event, pattern_config)
            elif pattern_type == "error_rate":
                return await self._check_error_rate_pattern(event, pattern_config)
            elif pattern_type == "anomaly":
                return await self._check_anomaly_pattern(event, pattern_config)
            else:
                return False
                
        except Exception as e:
            logger.error(f"Error checking pattern: {e}")
            return False
    
    async def _check_frequency_pattern(
        self,
        event: Dict[str, Any],
        pattern_config: Dict[str, Any]
    ) -> bool:
        """Check frequency-based pattern."""
        field = pattern_config.get("field")
        threshold = pattern_config.get("threshold", 100)
        window_seconds = pattern_config.get("window_seconds", 60)
        
        if field not in event:
            return False
        
        # Count events in time window
        current_time = datetime.now(timezone.utc)
        window_start = current_time - timedelta(seconds=window_seconds)
        
        count = 0
        for buffered_event in self.event_buffer:
            event_time = buffered_event.get("timestamp")
            if isinstance(event_time, str):
                event_time = datetime.fromisoformat(event_time.replace('Z', '+00:00'))
            
            if (event_time >= window_start and 
                buffered_event.get(field) == event.get(field)):
                count += 1
        
        return count >= threshold
    
    async def _check_error_rate_pattern(
        self,
        event: Dict[str, Any],
        pattern_config: Dict[str, Any]
    ) -> bool:
        """Check error rate pattern."""
        error_field = pattern_config.get("error_field", "status")
        error_values = pattern_config.get("error_values", ["error"])
        threshold = pattern_config.get("threshold", 0.1)
        window_seconds = pattern_config.get("window_seconds", 300)
        
        # Count errors and total events in window
        current_time = datetime.now(timezone.utc)
        window_start = current_time - timedelta(seconds=window_seconds)
        
        total_count = 0
        error_count = 0
        
        for buffered_event in self.event_buffer:
            event_time = buffered_event.get("timestamp")
            if isinstance(event_time, str):
                event_time = datetime.fromisoformat(event_time.replace('Z', '+00:00'))
            
            if event_time >= window_start:
                total_count += 1
                if buffered_event.get(error_field) in error_values:
                    error_count += 1
        
        if total_count == 0:
            return False
        
        error_rate = error_count / total_count
        return error_rate >= threshold
    
    async def _check_anomaly_pattern(
        self,
        event: Dict[str, Any],
        pattern_config: Dict[str, Any]
    ) -> bool:
        """Check anomaly pattern using statistical analysis."""
        field = pattern_config.get("field")
        threshold_stddev = pattern_config.get("threshold_stddev", 3.0)
        window_size = pattern_config.get("window_size", 100)
        
        if field not in event or not isinstance(event[field], (int, float)):
            return False
        
        # Collect values from buffer
        values = []
        for buffered_event in list(self.event_buffer)[-window_size:]:
            if field in buffered_event and isinstance(buffered_event[field], (int, float)):
                values.append(buffered_event[field])
        
        if len(values) < 10:  # Need minimum samples
            return False
        
        # Calculate statistics
        mean_val = np.mean(values)
        std_val = np.std(values)
        
        if std_val == 0:
            return False
        
        # Check if current value is anomalous
        z_score = abs((event[field] - mean_val) / std_val)
        return z_score >= threshold_stddev
    
    async def _trigger_alert(
        self,
        pattern_id: str,
        match_data: Dict[str, Any],
        event: Dict[str, Any]
    ) -> Optional[Dict[str, Any]]:
        """Trigger alert for pattern match."""
        try:
            # Find triggers for this pattern
            pattern_triggers = [
                (trigger_id, trigger_info)
                for trigger_id, trigger_info in self.triggers.items()
                if trigger_info["pattern_id"] == pattern_id
            ]
            
            alerts = []
            for trigger_id, trigger_info in pattern_triggers:
                # Execute trigger action
                action = trigger_info["action"]
                alert_result = await action(pattern_id, match_data, event)
                
                if alert_result:
                    alerts.append({
                        "trigger_id": trigger_id,
                        "pattern_id": pattern_id,
                        "alert_data": alert_result,
                        "triggered_at": datetime.now(timezone.utc)
                    })
                    
                    # Update trigger execution count
                    self.triggers[trigger_id]["executions"] += 1
                    self.metrics["alerts_triggered"] += 1
            
            return alerts[0] if alerts else None
            
        except Exception as e:
            logger.error(f"Error triggering alert: {e}")
            return None
    
    async def _event_processing_worker(self) -> None:
        """Background worker for event processing optimization."""
        while True:
            try:
                # Cleanup old events from buffer
                await self._cleanup_old_events()
                
                # Optimize patterns based on performance
                await self._optimize_patterns()
                
                await asyncio.sleep(60)  # Run every minute
                
            except Exception as e:
                logger.error(f"Error in event processing worker: {e}")
                await asyncio.sleep(60)
    
    async def _cleanup_old_events(self) -> None:
        """Remove old events from buffer."""
        if not self.event_buffer:
            return
        
        current_time = datetime.now(timezone.utc)
        max_age = timedelta(hours=1)  # Keep events for 1 hour max
        
        # Remove events older than max_age
        while self.event_buffer:
            oldest_event = self.event_buffer[0]
            event_time = oldest_event.get("timestamp")
            
            if isinstance(event_time, str):
                event_time = datetime.fromisoformat(event_time.replace('Z', '+00:00'))
            
            if current_time - event_time > max_age:
                self.event_buffer.popleft()
            else:
                break
    
    async def _optimize_patterns(self) -> None:
        """Optimize patterns based on performance metrics."""
        # Remove patterns that haven't matched in a long time
        current_time = datetime.now(timezone.utc)
        patterns_to_remove = []
        
        for pattern_id, pattern_info in self.patterns.items():
            created_at = pattern_info["created_at"]
            matches = pattern_info["matches"]
            
            # Remove patterns older than 24 hours with no matches
            if (current_time - created_at > timedelta(hours=24) and matches == 0):
                patterns_to_remove.append(pattern_id)
        
        for pattern_id in patterns_to_remove:
            del self.patterns[pattern_id]
            logger.info(f"Removed unused pattern: {pattern_id}")


# ================== UTILITY FUNCTIONS ==================

def performance_monitor(func):
    """Decorator to monitor function performance."""
    @wraps(func)
    async def wrapper(*args, **kwargs):
        start_time = time.perf_counter()
        try:
            result = await func(*args, **kwargs)
            return result
        finally:
            execution_time = time.perf_counter() - start_time
            logger.debug(f"Function {func.__name__} executed in {execution_time:.4f}s")
    return wrapper


@performance_monitor
async def create_processing_pipeline(
    processors: List[Callable],
    config: Optional[ProcessorConfig] = None
) -> Callable:
    """Create a processing pipeline from a list of processors."""
    if not config:
        config = ProcessorConfig()
    
    async def pipeline(data: Any) -> Any:
        current_data = data
        for processor in processors:
            current_data = await processor(current_data)
        return current_data
    
    return pipeline
